/**
 * Shared Swing helpers for the panel tabs (Session and Targeted render the same kind of
 * summary block, icon grids, cost rows and death rows).
 */
final class PanelUi
{
	static final Color SUPPLIES_COLOR = new Color(120, 190, 255);
	static final Color SPELL_COLOR = new Color(180, 140, 255);
	static final Color TELEPORT_COLOR = new Color(120, 220, 200);
	static final Color AMMO_COLOR = new Color(230, 190, 110);
	static final Color SKILLING_COLOR = new Color(200, 165, 120);
	static final Color DEATH_COLOR = ColorScheme.PROGRESS_ERROR_COLOR;
	static final Color GAIN_COLOR = new Color(120, 210, 140);
	static final Color LOSS_COLOR = new Color(225, 120, 120);
	static final Color GAIN_CELL = new Color(35, 60, 42);
	static final Color LOSS_CELL = new Color(64, 38, 38);

	static final int GRID_COLS = 5;
	static final int CELL = 36;

	private PanelUi()
	{
	}

	static Color colorFor(String kind)
	{
		switch (kind)
		{
			case "spell":
				return SPELL_COLOR;
			case "teleport":
				return TELEPORT_COLOR;
			case "ammo":
				return AMMO_COLOR;
			case "skilling":
				return SKILLING_COLOR;
			case "death":
				return DEATH_COLOR;
			case "npc_loot":
			case "pvp_loot":
			case "event_loot":
			case "pickpocket":
			case "pickup":
			case "alch":
			case "skilling_gain":
				return GAIN_COLOR;
			default:
				return SUPPLIES_COLOR;
		}
	}

	/** A "Label value" cell: grey label, coloured value, packed two per row. */
	static JLabel statCell(String label, String value, Color valueColor, boolean bold)
	{
		final String hex = String.format("#%02x%02x%02x",
			valueColor.getRed(), valueColor.getGreen(), valueColor.getBlue());
		final JLabel l = new JLabel("<html>"
			+ (label.isEmpty() ? "" : "<font color='#a0a0a0'>" + label + "</font> ")
			+ "<font color='" + hex + "'>" + value + "</font></html>");
		l.setFont(bold
			? l.getFont().deriveFont(Font.BOLD)
			: FontManager.getRunescapeSmallFont());
		return l;
	}

	/**
	 * The headline net row(s) for a live run's 2-column stat grid. Normally one bold
	 * "Potential net" cell (collected loot at GE − cost) with {@code topRight} beside it. Once
	 * something has been alched / banked this run, "Actual net" (real proceeds + loot still held
	 * − cost) leads in bold and "Potential net" drops to a plain sub-line below it - so a run
	 * that's cashed out doesn't read as a pure loss.
	 */
	static void addNetCells(JPanel grid, ProfitLossCalculatorPanel.View view, JLabel topRight)
	{
		final long potential = view.getNet();
		final boolean cashed = view.getRealisedSoFar() > 0 || view.getBankedSoFar() > 0;
		if (cashed)
		{
			final long actual = view.getActualNet();
			grid.add(statCell("Actual net", sign(actual), actual >= 0 ? GAIN_COLOR : LOSS_COLOR, true));
			grid.add(topRight);
			grid.add(statCell("Potential net", sign(potential),
				potential >= 0 ? GAIN_COLOR : LOSS_COLOR, false));
			grid.add(new JLabel());
		}
		else
		{
			grid.add(statCell("Potential net", sign(potential),
				potential >= 0 ? GAIN_COLOR : LOSS_COLOR, true));
			grid.add(topRight);
		}
	}

	/** Adds "Realised" / "Banked" cells to the 2-column stat grid when loot has been alched or
	 *  banked mid-run. Real realised / banked totals live in the History tab - this is a hint
	 *  that something has been cashed out or secured this run. */
	static void addRealisedSoFar(JPanel grid, ProfitLossCalculatorPanel.View view)
	{
		if (view.getRealisedSoFar() > 0)
		{
			grid.add(statCell("Realised", "+" + gpPlain(view.getRealisedSoFar()), GAIN_COLOR, false));
			grid.add(new JLabel());
		}
		if (view.getBankedSoFar() > 0)
		{
			grid.add(statCell("Banked", gpPlain(view.getBankedSoFar()), SUPPLIES_COLOR, false));
			grid.add(new JLabel());
		}
	}

	static void fillGrid(JPanel grid, List<ProfitLossCalculatorPanel.GridItem> items, Color cell, ItemManager itemManager)
	{
		grid.removeAll();
		if (items.isEmpty())
		{
			grid.setVisible(false);
			return;
		}
		grid.setVisible(true);
		final int rows = (items.size() + GRID_COLS - 1) / GRID_COLS;
		grid.setMaximumSize(new Dimension(Integer.MAX_VALUE, rows * CELL + (rows - 1) * 2));
		grid.setAlignmentX(Component.LEFT_ALIGNMENT);
		for (int i = 0; i < rows * GRID_COLS; i++)
		{
			final JPanel slot = new JPanel(new BorderLayout());
			slot.setBackground(cell);
			if (i < items.size())
			{
				final ProfitLossCalculatorPanel.GridItem gi = items.get(i);
				final JLabel icon = new JLabel();
				icon.setHorizontalAlignment(SwingConstants.CENTER);
				icon.setVerticalAlignment(SwingConstants.CENTER);
				final String tip = gi.getName() + "  ·  " + gp(gi.getValue())
					+ (gi.getQty() > 1 ? "  (" + QuantityFormatter.formatNumber(gi.getQty()) + ")" : "");
				icon.setToolTipText(tip);
				slot.setToolTipText(tip);
				final AsyncBufferedImage img = itemManager.getImage(gi.getId(), gi.getQty(), gi.getQty() > 1);
				if (img != null)
				{
					img.addTo(icon);
				}
				slot.add(icon);
			}
			grid.add(slot);
		}
	}

	static JPanel eventLine(ProfitLossCalculatorPanel.EventLine line)
	{
		final JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, colorFor(line.getKind())),
			BorderFactory.createEmptyBorder(2, 5, 2, 5)));

		final JLabel left = new JLabel((line.getTime().isEmpty() ? "" : line.getTime() + "  ") + line.getLabel());
		left.setFont(FontManager.getRunescapeSmallFont());
		if (line.getTooltip() != null && !line.getTooltip().isEmpty())
		{
			left.setToolTipText(line.getTooltip());
			row.setToolTipText(line.getTooltip());
		}

		final JLabel right = new JLabel(gp(line.getGp()));
		right.setFont(FontManager.getRunescapeSmallFont());
		right.setForeground(colorFor(line.getKind()));
		right.setHorizontalAlignment(SwingConstants.RIGHT);

		row.add(left, BorderLayout.CENTER);
		row.add(right, BorderLayout.EAST);
		return row;
	}

	/** "#37  14:32" left (plus the mob name, for a Slayer run's multi-species list), that
	 *  kill's collected value right, items in the tooltip. */
	static JPanel killRow(ProfitLossCalculatorPanel.KillRow k)
	{
		final JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, k.getCollected() >= 0 ? GAIN_COLOR : LOSS_COLOR),
			BorderFactory.createEmptyBorder(2, 5, 2, 5)));

		final String label = "#" + k.getIndex() + "   " + k.getTime()
			+ (k.getMobName() == null || k.getMobName().isEmpty() ? "" : "   " + k.getMobName());
		final JLabel left = new JLabel(label);
		left.setFont(FontManager.getRunescapeSmallFont());
		final JLabel right = new JLabel(sign(k.getCollected()));
		right.setFont(FontManager.getRunescapeSmallFont());
		right.setForeground(GAIN_COLOR);
		right.setHorizontalAlignment(SwingConstants.RIGHT);

		if (k.getTooltip() != null)
		{
			row.setToolTipText(k.getTooltip());
			left.setToolTipText(k.getTooltip());
			right.setToolTipText(k.getTooltip());
		}
		row.add(left, BorderLayout.CENTER);
		row.add(right, BorderLayout.EAST);
		return row;
	}

	/** One target mob's block in a multi-target Target Farm: name/kills header, net
	 *  right-aligned and coloured, a "gained X · cost Y" sub-line, gp/kill, and that mob's own
	 *  gain icon grid (losses stay a farm-wide figure - cost isn't tracked per item per mob). */
	static JPanel mobFarmBlock(ProfitLossCalculatorPanel.MobFarmBlock mb, ItemManager itemManager)
	{
		final Color accent = mb.getNet() >= 0 ? GAIN_COLOR : LOSS_COLOR;

		final JPanel box = new JPanel(new BorderLayout());
		box.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		box.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 3, 0, 0, accent),
			BorderFactory.createEmptyBorder(4, 6, 6, 6)));

		final JPanel line1 = new JPanel(new BorderLayout(6, 0));
		line1.setOpaque(false);
		final JLabel name = new JLabel(mb.getMobName()
			+ (mb.getKills() > 0 ? "  ×" + QuantityFormatter.formatNumber(mb.getKills()) : ""));
		final JLabel net = new JLabel(sign(mb.getNet()));
		net.setForeground(accent);
		net.setHorizontalAlignment(SwingConstants.RIGHT);
		line1.add(name, BorderLayout.CENTER);
		line1.add(net, BorderLayout.EAST);

		final String sub1 = "gained " + gpPlain(mb.getGains())
			+ (mb.getLosses() > 0 ? "  ·  cost " + gpPlain(mb.getLosses()) : "");
		final String sub2 = mb.getKills() > 0 ? sign(mb.getGpPerKill()) + "/kill" : "No kills yet";

		final JPanel head = new JPanel(new BorderLayout());
		head.setOpaque(false);
		head.add(line1, BorderLayout.NORTH);
		head.add(smallGrey(sub1), BorderLayout.CENTER);
		head.add(smallGrey(sub2), BorderLayout.SOUTH);
		box.add(head, BorderLayout.NORTH);

		if (!mb.getGainItems().isEmpty())
		{
			final JPanel icons = new JPanel(new GridLayout(0, GRID_COLS, 1, 1));
			icons.setOpaque(false);
			icons.setBorder(BorderFactory.createEmptyBorder(5, 0, 0, 0));
			fillGrid(icons, mb.getGainItems(), GAIN_CELL, itemManager);
			box.add(icons, BorderLayout.CENTER);
		}
		return box;
	}

	private static JLabel smallGrey(String text)
	{
		final JLabel l = new JLabel(text);
		l.setFont(FontManager.getRunescapeSmallFont());
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		return l;
	}

	static JPanel deathRow(ProfitLossCalculatorPanel.DeathRow d, ProfitLossCalculatorPanel.Controls controls)
	{
		final JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 6, 4, 6)));
		p.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		final JLabel head = new JLabel("Death - lost " + gp(d.getFullValue()));
		head.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(head);

		final JLabel items = new JLabel("<html>" + escape(d.getItemSummary()) + "</html>");
		items.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		items.setFont(FontManager.getRunescapeSmallFont());
		items.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(items);

		final JLabel status = new JLabel(d.isReturned()
			? "Items back - confirm the fee paid:"
			: "Pending - not reclaimed yet. If reclaimed, set fee:");
		status.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		status.setFont(FontManager.getRunescapeSmallFont());
		status.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.add(status);

		final JPanel controlsRow = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 2));
		controlsRow.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		controlsRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JTextField fee = new JTextField(String.valueOf(d.getEstimatedFee()), 7);
		final JButton confirm = new JButton("Confirm");
		confirm.addActionListener(e ->
		{
			try
			{
				controls.onConfirmDeath(d.getDeathId(), Long.parseLong(fee.getText().trim().replace(",", "")));
			}
			catch (NumberFormatException ignored)
			{
				// leave the field for the user to fix
			}
		});
		final JButton free = new JButton("Free");
		free.addActionListener(e -> controls.onGravestone(d.getDeathId()));
		controlsRow.add(fee);
		controlsRow.add(confirm);
		controlsRow.add(free);
		p.add(controlsRow);
		return p;
	}

	static JLabel sectionLabel(String text)
	{
		final JLabel l = new JLabel(text.toUpperCase());
		l.setFont(l.getFont().deriveFont(l.getFont().getSize2D() - 1f).deriveFont(Font.BOLD));
		l.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		l.setBorder(BorderFactory.createEmptyBorder(2, 0, 3, 0));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	static Component vgap(int h)
	{
		return Box.createVerticalStrut(h);
	}

	/** Left-align and let a component fill the panel width; height is left to the layout. */
	static <T extends JComponent> T stretch(T c)
	{
		c.setAlignmentX(Component.LEFT_ALIGNMENT);
		c.setMaximumSize(new Dimension(Integer.MAX_VALUE, c.getMaximumSize().height));
		return c;
	}

	static String sign(long v)
	{
		return (v >= 0 ? "+" : "") + gpPlain(v);
	}

	static String escape(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	static String gp(long v)
	{
		return QuantityFormatter.formatNumber(v) + " gp";
	}

	static String gpPlain(long v)
	{
		return QuantityFormatter.formatNumber(v);
	}

	/** A duration for the panel: "24s", "2m 05s", "1h 20m". */
	static String secs(long s)
	{
		if (s <= 0)
		{
			return "0s";
		}
		if (s < 60)
		{
			return s + "s";
		}
		if (s < 3600)
		{
			return (s / 60) + "m " + String.format("%02ds", s % 60);
		}
		return (s / 3600) + "h " + ((s % 3600) / 60) + "m";
	}
}

