@ConfigGroup(ProfitLossCalculatorConfig.GROUP)
public interface ProfitLossCalculatorConfig extends Config
{
	String GROUP = "profit-loss-calculator";

	@ConfigSection(
		name = "Death cost",
		description = "How the Death's Office reclaim fee is estimated",
		position = 0
	)
	String deathSection = "death";

	@ConfigSection(
		name = "Ammo & teleports",
		description = "Extra cost sources, all priced live off the GE",
		position = 1
	)
	String extrasSection = "extras";

	@ConfigSection(
		name = "Income",
		description = "What counts as gp coming in, and how it is valued",
		position = 2
