	/** Config group before the plugin was renamed from "Session Cost Tracker". */
	private static final String LEGACY_CONFIG_GROUP = "sessioncosttracker";

	/**
	 * One-time move of saved settings from the pre-rename config group to
	 * {@link ProfitLossCalculatorConfig#GROUP}. Without this every user's settings would
	 * silently reset when they update. Runs once, then leaves a marker so it never repeats.
	 */
	private void migrateSettings()
	{
		final String group = ProfitLossCalculatorConfig.GROUP;
		if (configManager.getConfiguration(group, "migratedFrom") != null)
		{
			return;
		}
		final String prefix = LEGACY_CONFIG_GROUP + ".";
		for (String wholeKey : configManager.getConfigurationKeys(prefix))
		{
			final String key = wholeKey.substring(prefix.length());
			final String value = configManager.getConfiguration(LEGACY_CONFIG_GROUP, key);
			if (value != null && configManager.getConfiguration(group, key) == null)
			{
				configManager.setConfiguration(group, key, value);
			}
			configManager.unsetConfiguration(LEGACY_CONFIG_GROUP, key);
		}
		configManager.setConfiguration(group, "migratedFrom", LEGACY_CONFIG_GROUP);
	}

	@Override
	protected void startUp()
	{
		migrateSettings();
		panel = new ProfitLossCalculatorPanel(this, itemManager, !config.welcomeSeen());

		BufferedImage icon = ImageUtil.loadImageResource(getClass(), "panel_icon.png");
		navButton = NavigationButton.builder()
			.tooltip("Profit Loss Calculator")
			.icon(icon)
			.priority(7)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
		overlayManager.add(overlay);
		if (config.showNoSessionWarning())
		{
			overlayManager.add(noSessionOverlay);
			bankScanQueued = true;
		}

		history.start();
		history.load(this::pushHistory);
		// plugin enabled while already in-game - onGameTick starts the ambient run once the
		// item containers are confirmed loaded (see ambientStartPending)
		ambientStartPending = true;
		refreshView();
	}

	@Override
	protected void shutDown()
	{
		if (session != null && !sessionFinished)
		{
			stopSession();
		}
		overlayManager.remove(overlay);
		overlayManager.remove(noSessionOverlay);
		clientToolbar.removeNavigation(navButton);
		logger.close();
		history.stop();
		panel = null;
		session = null;
		ambientStartPending = false;
		pendings.clear();
		bankTiles.clear();
		bankObjectIdCache.clear();
		// re-seed the GE tracker from the freshly-loaded slot state if the plugin is re-enabled
		geSlotsSeeded = false;
	}

	/** Lifetime history snapshot from the history executor - handed to the History tab.
	 *  Item names are resolved here on the client thread (ItemManager forbids the EDT) and
	 *  passed along so the panel never touches ItemManager for names. */
	private void pushHistory(SessionHistory.Snapshot lifetime)
	{
		clientThread.invoke(() ->
		{
			final Map<Integer, String> names = new HashMap<>();
			for (SessionHistory.MobStats m : lifetime.getMobs())
			{
				if (m.getItems() == null)
				{
					continue;
				}
				for (long[] it : m.getItems())
				{
					names.computeIfAbsent((int) it[0], this::itemName);
				}
			}
			for (SessionHistory.SaleRow s : lifetime.getSales())
			{
				names.computeIfAbsent(s.getItemId(), this::itemName);
			}
			for (SessionHistory.ItemStat it : lifetime.getItems())
			{
				names.computeIfAbsent(it.getItemId(), this::itemName);
			}
			final ProfitLossCalculatorPanel p = panel;
			if (p != null)
			{
				SwingUtilities.invokeLater(() -> p.renderHistory(lifetime, names));
			}
		});
	}

	/** The run's title: the farmed mob, the current Slayer task name, or "Session". */
	private String sessionTitle()
	{
		if (session == null)
		{
			return "Session";
		}
		if (session.isTargeted())
		{
			return String.join(", ", session.getTargetMobs());
		}
		if (session.isSlayer())
		{
			final String task = slayerTracker.getTaskName();
			return task == null || task.isEmpty() ? "Slayer" : task;
		}
		return "Session";
	}

