	// ------------------------------------------------------------------ session lifecycle

	/** Begin the always-on background run. */
	private void startAmbient()
	{
		startRun(Session.RunMode.SESSION, Collections.emptyList(), true);
		lastAmbientCheckpointTick = client.getTickCount();
	}

	/** Begin a run. {@code mode} picks plain session / Targeted farm / Slayer task;
	 *  {@code targetMobs} is only meaningful for {@link Session.RunMode#TARGETED} - the farm's
	 *  initial target group (more can be added later via {@link #onAddTargetMob});
	 *  {@code ambient} marks the auto-started background run. */
	private void startRun(Session.RunMode mode, List<String> targetMobs, boolean ambient)
	{
		final Instant now = Instant.now();

		ambientStartPending = false;
		lastKnownInv = ContainerSnapshot.of(client.getItemContainer(InventoryID.INV));
		lastKnownWorn = ContainerSnapshot.of(client.getItemContainer(InventoryID.WORN));
		pendings.clear();
		pendingDeath = null;
		deathWindowTicks = 0;
		deathGraveConfirmed = false;
		deathLossAcc.clear();
		recentReclaimFee = -1;
		recentReclaimFeeTick = -1;
		lastKillByName.clear();
		lastPlainKillTick = -100;
		lastPlainKillName = "";
		currentOpponent = null;
		opponentTick = -100;
		ammoGpCharged = 0;
		chargedWeaponGpCharged = 0;
		stateHistory.clear();
		pushStateHistory();

		teleTabCache.clear();
		bankOpen = client.getWidget(InterfaceID.Bankmain.ITEMS) != null;
		prevTickItems = trackedItems();
		if (teleChargesById.isEmpty())
		{
			teleChargesById = buildTeleChargeMap();
			teleCostPerCharge = buildTelePerChargeCost();
		}
		ammoTracker.reset(ammoOwned());
		chargedWeaponTracker.reset();
		skillingTracker.reset(currentSkillXp());
		blueMoonFreeze.reset();
		pickupTracker.reset();
		lootCollector.clear();
		dropIntent.clear();
		droppedOut.clear();
		alchCredited.clear();
		pendingBankMoves.clear();
		pendingAlch.clear();
		pendingAlchMob.clear();
		prevBankInv = null;
		frozenView = null;

		if (config.writeSessionFile())
		{
			logger.open(now);
		}
		final List<String> targets = targetMobs == null ? Collections.emptyList() : targetMobs;
		if (mode == Session.RunMode.SLAYER)
		{
			slayerTracker.reset();
			// seed with whatever's already spawned nearby - onNpcSpawned only fires for NPCs
			// that spawn *after* this point, so anything already standing here needs an
			// explicit first read or its kill silently wouldn't match the task
			slayerTracker.accumulateTargets(slayerService);
		}
		logger.line("session_start")
			.put("startedAt", now.toString())
			.put("mode", mode.name())
			.put("target", targets.isEmpty() ? null : String.join(", ", targets))
			.submit();

		session = new Session(now);
		session.setMode(mode);
		session.setAmbient(ambient);
		targets.forEach(session::addTargetMob);
		sessionFinished = false;
		refreshView();
	}

	private void setPaused(boolean paused)
	{
		if (session == null || sessionFinished || session.isPaused() == paused)
		{
			return;
		}
		session.setPaused(paused);
		// re-base the trackers past the paused stretch so banking / afk doesn't accrue
		ammoTracker.reset(ammoOwned());
		skillingTracker.reset(currentSkillXp());
		pickupTracker.reset();
		prevTickItems = trackedItems();
		if (!paused && session.isSlayer())
		{
			// onNpcSpawned doesn't accumulate while paused, so anything that spawned nearby
			// (or was already there in a new area) during the pause needs the same explicit
			// catch-up read as a fresh Start
			slayerTracker.accumulateTargets(slayerService);
		}
		logger.line(paused ? "session_pause" : "session_resume").submit();
		refreshView();
	}

	/** A {@link RunRecord} for the live (not finalised) session - the shape {@link #stopSession}
	 *  writes, reused to checkpoint the ambient run mid-flight. */
	private RunRecord currentRunRecord()
	{
		final Session.RunMode mode = session.getMode();
		final String kind = mode == Session.RunMode.TARGETED ? "farm"
			: mode == Session.RunMode.SLAYER ? "slayer" : "session";
		final long dur = java.time.Duration.between(session.getStartTime(), Instant.now()).getSeconds();
		return new RunRecord(SessionHistory.SCHEMA, kind, session.getStartTime().toString(),
			Instant.now().toString(), dur, config.incomeValuation().name(), perMobRollup());
	}

	/** Write the ambient run to history.jsonl (upsert by start) so its loot can be matched
	 *  against GE sales / bank deposits before the run ends on logout. */
	private void checkpointAmbient()
	{
		if (session == null || sessionFinished || !session.isAmbient())
		{
			return;
		}
		lastAmbientCheckpointTick = client.getTickCount();
		history.checkpoint(currentRunRecord(), this::pushHistory);
	}

	private void stopSession()
	{
		if (session == null || sessionFinished)
		{
			return;
		}
		if (deathWindowTicks > 0)
		{
			deathWindowTicks = 0;
			finalizeDeath();
		}

		for (DeathEntry e : pendings.values())
		{
			if (e.getLostItems().isEmpty())
			{
				continue;
			}
			if (e.getState() == DeathEntry.State.PENDING)
			{
				e.setState(DeathEntry.State.LOST);
				e.setResolvedCost(e.getFullValue());
				e.setUserConfirmed(true);
				logResolved(e, "lost");
			}
			else if (e.getState() == DeathEntry.State.RETURNED && !e.isUserConfirmed()
				&& config.autoConfirmDeathFeeOnStop())
			{
				e.setResolvedCost(e.getEstimatedFee());
				e.setUserConfirmed(true);
				logResolved(e, "auto-fee");
			}
		}

		session.setEndTime(Instant.now());
		sessionFinished = true;

		final long collected = collectedTotal();
		final long potential = potentialTotal();
		final SessionSummary summary = SessionSummary.of(session, collected, potential);
		final long durationSec = java.time.Duration.between(
			session.getStartTime(), session.getEndTime()).getSeconds();
		final Session.RunMode mode = session.getMode();
		final boolean targeted = mode == Session.RunMode.TARGETED;
		final Map<String, RunRecord.MobRun> perMob = perMobRollup();

		logger.line("session_stop")
			.put("sessionId", sessionId())
			.put("target", String.join(", ", session.getTargetMobs()))
			.put("durationSeconds", durationSec)
			.put("valuation", config.incomeValuation().name())
			.put("summary", summary.toJsonFields())
			.put("ammoItems", ammoItemsLog(session.getAmmoStats()))
			.put("chargedWeapons", chargedWeaponsLog())
			.put("kills", killsLog())
			.put("perMob", perMob)
			.submit();
		final Path file = logger.path();
		logger.close();

		// every run - session, farm or slayer task - feeds the per-mob lifetime history. An
		// ambient run that never touched anything is dropped (idle logins shouldn't litter
		// history.jsonl); an explicit Start/Stop is always recorded even if empty. checkpoint()
		// upserts by start, so a stop after periodic ambient checkpoints replaces that line
		// instead of appending a duplicate.
		final String kind = targeted ? "farm" : mode == Session.RunMode.SLAYER ? "slayer" : "session";
		final String runStart = session.getStartTime().toString();
		final boolean recordRun = !perMob.isEmpty() || !session.isAmbient()
			|| !pendingBankMoves.isEmpty() || !pendingAlch.isEmpty();
		if (recordRun)
		{
			history.checkpoint(new RunRecord(
				SessionHistory.SCHEMA,
				kind,
				runStart,
				session.getEndTime().toString(),
				durationSec,
				config.incomeValuation().name(),
				perMob), this::pushHistory);

			// the run is now in history.jsonl - replay anything banked / alched during it so the
			// FIFO attribution can land it on this run (preferRunStart)
			for (long[] mv : pendingBankMoves)
			{
				history.applyBankMove((int) mv[0], mv[1], runStart, this::pushHistory);
			}
			for (int i = 0; i < pendingAlch.size(); i++)
			{
				final long[] a = pendingAlch.get(i);
				final String alchMob = i < pendingAlchMob.size() ? pendingAlchMob.get(i) : null;
				history.applyAlch((int) a[0], a[1], alchMob, runStart, Instant.now().toString(), this::pushHistory);
			}
		}
		pendingBankMoves.clear();
		pendingAlch.clear();
		pendingAlchMob.clear();

		if (client.getGameState() == GameState.LOGGED_IN)
		{
			final long net = summary.net();
			final long kills = session.getBossKills();
			final StringBuilder msg = new StringBuilder("[Profit Loss Calculator] ");
			if (targeted)
			{
				long farmNet = 0;
				for (RunRecord.MobRun mr : perMob.values())
				{
					farmNet += mr.getGained() - mr.getCost();
				}
				msg.append(String.join(", ", session.getTargetMobs())).append(" farm: ")
					.append(farmNet >= 0 ? "+" : "-").append(gp(Math.abs(farmNet)));
				if (kills > 0)
				{
					msg.append(" over ").append(kills).append(" kill(s) (")
						.append(gp(farmNet / kills)).append("/kill)");
				}
			}
			else if (mode == Session.RunMode.SLAYER)
			{
				long slayerNet = 0;
				for (RunRecord.MobRun mr : perMob.values())
				{
					slayerNet += mr.getGained() - mr.getCost();
				}
				final String task = slayerTracker.getTaskName();
				msg.append(task == null || task.isEmpty() ? "Slayer" : task).append(" task: ")
					.append(slayerNet >= 0 ? "+" : "-").append(gp(Math.abs(slayerNet)));
				if (kills > 0)
				{
					msg.append(" over ").append(kills).append(" kill(s) (")
						.append(gp(slayerNet / kills)).append("/kill)");
				}
			}
			else
			{
				msg.append(net >= 0 ? "Profit: " : "Loss: ")
					.append(gp(Math.abs(net)))
					.append("  (collected ").append(gp(collected))
					.append(" − cost ").append(gp(session.total())).append(')');
				if (potential != collected)
				{
					msg.append(", ").append(gp(potential)).append(" dropped");
				}
				if (kills > 0)
				{
					msg.append(" over ").append(kills).append(" kill(s)");
				}
			}
			if (session.atRiskTotal() > 0)
			{
				msg.append(" (").append(gp(session.atRiskTotal())).append(" at risk)");
			}
			client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg.toString(), null);
		}
		if (file != null)
		{
			log.debug("session log written to {}", file);
		}
		log.debug("session summary:\n{}", summary.toPlainText());

		// lock the finished session's view at today's prices
		frozenView = buildView();
		refreshView();
	}

	private void resolveDeath(int deathId, long fee, boolean gravestone)
	{
		final DeathEntry e = pendings.get(deathId);
		if (e == null)
		{
			return;
		}
		e.setState(DeathEntry.State.RETURNED);
		e.setResolvedCost(fee);
		e.setEstimatedFee(fee);
		e.setUserConfirmed(true);
		logResolved(e, gravestone ? "gravestone" : "fee-confirmed");
		if (sessionFinished)
		{
			// re-lock the frozen view now that this death has a confirmed cost
			frozenView = null;
			frozenView = buildView();
		}
		refreshView();
	}

	private void logResolved(DeathEntry e, String outcome)
	{
		logger.line("death_resolved")
			.put("deathId", e.getId())
			.put("outcome", outcome)
			.put("gp", e.getResolvedCost())
			.submit();
	}

	// ------------------------------------------------------------------ events

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		final GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			bankOpen = false;
			// drop the skill-XP baseline - a relogin fires a StatChanged storm with the real
			// totals, which would otherwise register as one huge "action" per skill
			skillingTracker.reset(Collections.emptyMap());
		}
		if (state == GameState.LOGGING_IN || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
		{
			// the GE re-sends every slot for a few ticks after login - GeSaleTracker ignores
			// EMPTY during this window so it doesn't wipe the restored baseline
			lastGeLoginTick = client.getTickCount();
		}
		if (state == GameState.LOGIN_SCREEN && session != null && !sessionFinished && session.isAmbient())
		{
			// end this play-session's ambient run so History gets one tidy row per session
			stopSession();
		}
		if (state == GameState.LOGGED_IN)
		{
			// don't start the ambient run here - the inventory / equipment containers usually
			// haven't arrived yet, and their first load would read as a pile of picked-up loot.
			// onGameTick starts it once the containers are actually populated.
			ambientStartPending = true;
		}
	}

	/** GE tax re-sends every slot for a couple of ticks after login. */
	private static final int GE_LOGIN_BURST_TICKS = 2;

	/**
	 * A GE offer slot changed. When it is a sell fill, hand the delta to
	 * {@link SessionHistory#applySale} which matches it back (FIFO, oldest run first) to the
	 * loot that produced it. Buys are ignored - supplies are costed by consumption. The
	 * per-slot baseline is persisted after every event so a sale that finishes while logged
	 * out is attributed once, not twice.
	 */
	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (!config.trackRealisedGp())
		{
			return;
		}
		if (!geSlotsSeeded)
		{
			geSaleTracker.restore(history.geSlots());
			geSlotsSeeded = true;
		}
		final GrandExchangeOffer offer = event.getOffer();
		if (offer == null)
		{
			return;
		}
		final boolean loginBurst = client.getTickCount() <= lastGeLoginTick + GE_LOGIN_BURST_TICKS;
		final GeSaleTracker.TaxFn taxFn = config.deductGeTax() ? GeTax::tax : null;
		final java.util.List<GeSaleTracker.Sale> sales = geSaleTracker.onOffer(
			event.getSlot(), offer.getItemId(), offer.getState(),
			offer.getQuantitySold(), offer.getSpent(), loginBurst, taxFn);
		history.saveGeSlots(geSaleTracker.snapshot());
		for (GeSaleTracker.Sale sale : sales)
		{
			log.debug("GE sale: {} x{} for {} (tax {})",
				sale.getItemId(), sale.getQty(), sale.getGross(), sale.getTax());
			history.applySale(sale, this::pushHistory);
		}
	}

	@Subscribe
	public void onWorldViewLoaded(WorldViewLoaded event)
	{
		// the scene just (re)loaded - refresh the bank booth / chest / banker positions the
		// "no session" reminder checks against, on the next tick when the scene is settled
		if (config.showNoSessionWarning() && event.getWorldView().isTopLevel())
		{
			bankScanQueued = true;
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!ProfitLossCalculatorConfig.GROUP.equals(event.getGroup()))
		{
			return;
		}

		if ("showNoSessionWarning".equals(event.getKey()))
		{
			// Add / remove the overlay outright rather than leaving it registered and letting
			// render() no-op, so turning the setting off clears it from the screen immediately.
			if (config.showNoSessionWarning())
			{
				overlayManager.add(noSessionOverlay);
				bankScanQueued = true;
			}
			else
			{
				overlayManager.remove(noSessionOverlay);
				bankTiles.clear();
				bankScanQueued = false;
			}
			return;
		}

		if ("ambientTracking".equals(event.getKey()))
		{
			clientThread.invoke(() ->
			{
				if (config.ambientTracking())
				{
					// let onGameTick pick it up once logged in with containers loaded, unless a
					// foreground run is already going
					ambientStartPending = true;
				}
				else
				{
					// turning it off stops the background run right away - don't leave it "locked
					// on". A foreground Session / Farm / Slayer run keeps going.
					ambientStartPending = false;
					if (session != null && !sessionFinished && session.isAmbient())
					{
						// a run that actually recorded something is stopped properly (checkpointed
						// to History, chat summary); an untouched one is just dropped silently
						if (collectedTotal() > 0 || session.total() > 0 || !session.getDeaths().isEmpty())
						{
							stopSession();
						}
						session = null;
						sessionFinished = false;
						frozenView = null;
						refreshView();
					}
				}
			});
		}
	}

	/** A session exists and has not been stopped (may be paused). */
	private boolean tracking()
	{
		return session != null && !sessionFinished;
	}

	/** A session is running and not paused - costs should accrue. */
	private boolean accruing()
	{
		return tracking() && !session.isPaused();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		final int id = event.getContainerId();
		if (id != InventoryID.INV && id != InventoryID.WORN)
		{
			return;
		}

		if (id == InventoryID.INV)
		{
			lastKnownInv = ContainerSnapshot.of(event.getItemContainer());
			trackBankMoves();
		}
		else
		{
			lastKnownWorn = ContainerSnapshot.of(event.getItemContainer());
		}

		if (!tracking())
		{
			return;
		}

		if (deathWindowTicks > 0)
		{
			accumulateDeathLoss();
		}
		checkContainerReturn();
	}

	@Subscribe
	public void onGraphicChanged(GraphicChanged event)
	{
		if (!localPlayerAttackTracked(event.getActor()))
		{
			return;
		}
		for (ActorSpotAnim sa : event.getActor().getSpotAnims())
		{
			chargedAttackSignal(sa.getId());
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (localPlayerAttackTracked(event.getActor()))
		{
			chargedAttackSignal(event.getActor().getAnimation());
		}
	}

	/** True when {@code actor} is us and a charged-weapon attack should be counted right now. */
	private boolean localPlayerAttackTracked(Actor actor)
	{
		return actor != null && actor == client.getLocalPlayer()
			&& deathWindowTicks == 0 && accruing() && config.trackChargedWeapons();
	}

	/** An animation / spot-anim id fired on the player - if it is a charged weapon's attack
	 *  and that weapon is wielded, count one charge. */
	private void chargedAttackSignal(int id)
	{
		final ChargedWeapon weapon = ChargedWeapon.byAttackSignal(id);
		if (weapon != null && isWielding(weapon))
		{
			recordChargedAttack(weapon);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// always fed in (even idle) so the XP baseline stays current; reconcileSkilling reads
		// the active skill off it once per tick
		skillingTracker.record(event.getSkill(), event.getXp(), client.getTickCount());
	}

	/** Current total XP of every tracked skill, for seeding {@link #skillingTracker}. Empty
	 *  when not logged in - the tracker then re-seeds off the next {@code StatChanged}. */
	private Map<Skill, Integer> currentSkillXp()
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return Collections.emptyMap();
		}
		final Map<Skill, Integer> out = new HashMap<>();
		for (Skill s : SkillingTracker.TRACKED)
		{
			out.put(s, client.getSkillExperience(s));
		}
		return out;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (bankScanQueued)
		{
			bankScanQueued = false;
			scanNearbyBanks();
		}

		// drop the banked-loot diff baseline whenever no bank / deposit box is open, so the
		// next time one opens the first inventory change re-primes instead of reading as a
		// giant deposit. Runs even while idle - banking loot without a session still counts.
		if (prevBankInv != null && !bankInterfaceOpen())
		{
			prevBankInv = null;
		}

		// start the always-on ambient run, but only once the inventory AND equipment containers
		// have actually loaded - starting it on the LOGGED_IN event would take an empty baseline
		// and then bank the whole login inventory / worn kit as picked-up loot.
		if (ambientStartPending
			&& config.ambientTracking()
			&& (session == null || sessionFinished)
			&& client.getGameState() == GameState.LOGGED_IN
			&& client.getItemContainer(InventoryID.INV) != null
			&& client.getItemContainer(InventoryID.WORN) != null)
		{
			ambientStartPending = false;
			startAmbient();
			return; // let the fresh baseline settle one tick before diffing anything
		}

		// cheap field reads on the bundled Slayer plugin's own service - polled every tick
		// (even idle) so the Slayer tab's task preview stays live before Start is pressed.
		final boolean slayerOn = config.trackSlayerTask();
		final boolean taskChanged = slayerOn && slayerTracker.pollLiveInfo(slayerService);

		if (!tracking())
		{
			if (slayerOn)
			{
				refreshView();
			}
			return;
		}
		if (taskChanged)
		{
			// a run may be live and waiting on this - don't wait for an unrelated event to
			// push the header's task preview / progress up to date
			viewDirty = true;
		}
		updateBankState();
		pushStateHistory();
		trackOpponent();

		// Blue Moon's Weapon Freeze special seals the wielded weapon in a block of ice for a few
		// ticks and then hands it straight back - keep that round trip out of the ammo / skilling
		// / loot diffs below.
		blueMoonFreeze.update(
			client.getVarbitValue(VarbitID.PMOON_BOSS_BLUE_WEARPREVENT) > 0,
			weaponSlotItem(), client.getTickCount());
		final boolean weaponFrozen = blueMoonFreeze.active(client.getTickCount());

		if (session.isAmbient()
			&& client.getTickCount() - lastAmbientCheckpointTick >= AMBIENT_CHECKPOINT_TICKS
			&& (collectedTotal() > 0 || session.total() > 0))
		{
			checkpointAmbient();
		}

		// true once per tick, after this tick's container/varp changes have all landed - ammo,
		// teleports and income are all reconciled against this single settled state rather than
		// eagerly per event, so a multi-step action (e.g. loading a cannonball: inventory count
		// drops and the loaded-count varp rises as two separate events) can never be read as a
		// real fire/pickup just because one half of it landed before the other.
		final boolean accrue = deathWindowTicks == 0 && !bankOpen && !session.isPaused();

		// a thrown weapon ripped from the slot by Blue Moon's ice and handed back is not fired ammo
		reconcileAmmo(accrue && !weaponFrozen);

		// teleport charge drops and ground pickups are read once per tick so equipping /
		// unequipping jewellery (item moves inv<->worn within a tick, net zero) never looks
		// like a teleport. Skip while banking / paused - a deposit would look like spending
		// the last charge, a withdrawal like a pickup.
		final Map<Integer, Integer> curItems = trackedItems();
		// prevTickItems is empty only on the first accruing tick after a (re)start whose baseline
		// hasn't been captured yet (or a container load still in flight) - diffing against it
		// would treat everything you are holding as this tick's income. Skip until it is primed.
		if (accrue && !prevTickItems.isEmpty())
		{
			detectTeleports(prevTickItems, curItems);
			final Map<Integer, Integer> losses = ContainerSnapshot.lost(prevTickItems, curItems);
			final Map<Integer, Integer> gains = ContainerSnapshot.lost(curItems, prevTickItems);
			// the weapon Blue Moon froze in ice vanishing here (and reappearing a few ticks later
			// when the ice is broken) is neither a loss nor loot - drop it from both sides before
			// anything downstream can claim it
			blueMoonFreeze.filter(losses, gains);
			trackDrops(losses);
			// a food / potion that actually left the inventory after an Eat/Drink click - the
			// real "you consumed one" signal, as opposed to how many times the button was hit.
			// Clears the consumed item (and the lower-dose potion it turned into) from both maps
			// so the loot / skilling logic below can't also claim them.
			chargeConsumed(losses, gains);
			if (!gains.isEmpty())
			{
				reconcileIncome(gains);
			}
			// whatever inventory movement the loot / pickup / drop logic above didn't claim,
			// on a tick a tracked skill gained XP, is that skill's materials / product
			if (config.trackSkilling())
			{
				reconcileSkilling(gains, losses);
			}
		}
		prevTickItems = curItems;
		lootCollector.expire(client.getTickCount());

		if (deathWindowTicks > 0)
		{
			accumulateDeathLoss();
			if (--deathWindowTicks <= 0)
			{
				finalizeDeath();
			}
		}

		if (viewDirty)
		{
			viewDirty = false;
			refreshView();
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (!tracking())
		{
			return;
		}
		final ChatMessageType type = event.getType();
		if (type != ChatMessageType.GAMEMESSAGE && type != ChatMessageType.SPAM
			&& type != ChatMessageType.MESBOX)
		{
			return;
		}
		final String msg = Text.removeTags(event.getMessage());

		final Matcher payment = RECLAIM_PAYMENT.matcher(msg);
		if (payment.find())
		{
			try
			{
				recentReclaimFee = Long.parseLong(payment.group(1).replace(",", ""));
				recentReclaimFeeTick = client.getTickCount();
			}
			catch (NumberFormatException ignored)
			{
				// leave it
			}
			return;
		}

		if (GRAVE_CREATED.matcher(msg).find())
		{
			deathGraveConfirmed = true;
			return;
		}

		if (RECLAIM_SUCCESS.matcher(msg).find())
		{
			resolveOldestPendingFromReclaim();
		}
	}

	/**
	 * Inventory + equipment + rune pouch, as {@code itemId -> quantity}. This is the view the
	 * income / teleport diffing works against: runes that a pickup drops straight into the
	 * pouch (bypassing the inventory) still show as a gain. Moving runes between the inventory
	 * and the pouch nets to zero, and spending pouch runes on a cast is a loss nothing credits.
	 */
	private Map<Integer, Integer> trackedItems()
	{
		return ContainerSnapshot.union(
			ContainerSnapshot.union(lastKnownInv, lastKnownWorn), runePouchContents());
	}

	/** Rune-pouch contents as {@code itemId -> quantity}; empty when there is no pouch. */
	private Map<Integer, Integer> runePouchContents()
	{
		final EnumComposition runes;
		try
		{
			runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		}
		catch (RuntimeException ex)
		{
			return Collections.emptyMap();
		}
		if (runes == null)
		{
			return Collections.emptyMap();
		}
		final Map<Integer, Integer> out = new HashMap<>();
		for (int i = 0; i < RUNE_POUCH_TYPE_VARBITS.length; i++)
		{
			final int type = client.getVarbitValue(RUNE_POUCH_TYPE_VARBITS[i]);
			final int qty = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
			if (type <= 0 || qty <= 0)
			{
				continue;
			}
			final int itemId = runes.getIntValue(type);
			if (itemId > 0)
			{
				out.merge(itemId, qty, Integer::sum);
			}
		}
		return out;
	}

	private void pushStateHistory()
	{
		stateHistory.addLast(ContainerSnapshot.union(lastKnownInv, lastKnownWorn));
		while (stateHistory.size() > STATE_HISTORY_TICKS)
		{
			stateHistory.removeFirst();
		}
	}

	/** Inventory+equipment as it stood a couple of ticks before now - i.e. before the
	 *  death stripped it. Falls back to the current state only if there is no history. */
	private Map<Integer, Integer> preDeathSnapshot()
	{
		if (stateHistory.isEmpty())
		{
			return ContainerSnapshot.union(lastKnownInv, lastKnownWorn);
		}
		final List<Map<Integer, Integer>> h = new ArrayList<>(stateHistory);
		final int idx = Math.max(0, h.size() - 1 - PRE_DEATH_LOOKBACK_TICKS);
		return h.get(idx);
	}

	/**
	 * Bank open/close, read from the item-container widget each tick - {@code WidgetClosed}
	 * doesn't fire reliably for the bank. While open, ammo/teleport accrual pauses; on close
	 * the trackers re-base past whatever was deposited/withdrawn/swapped.
	 */
	private void updateBankState()
	{
		final boolean nowBank = client.getWidget(InterfaceID.Bankmain.ITEMS) != null;
		if (nowBank == bankOpen)
		{
			return;
		}
		bankOpen = nowBank;
		if (nowBank)
		{
			// about to shuffle loot around - make sure the ambient run's loot is recorded so a
			// deposit / a sale straight after can be matched to it
			checkpointAmbient();
		}
		else
		{
			ammoTracker.reset(ammoOwned());
			pickupTracker.reset();
			prevTickItems = trackedItems();
		}
	}

	/** True while the bank or a deposit box is open - the window banked-loot tracking runs in. */
	private boolean bankInterfaceOpen()
	{
		return client.getWidget(InterfaceID.Bankmain.ITEMS) != null
			|| client.getWidget(InterfaceID.BankDepositbox.INVENTORY) != null;
	}

	/**
	 * An inventory change while a bank / deposit box is open: diff it against the last one to
	 * find deposits (loot secured) and withdrawals (loot un-secured), and route them - buffered
	 * onto the current run, or straight to {@link SessionHistory#applyBankMove} when idle.
	 * {@link #prevBankInv} is nulled by {@link #onGameTick} whenever no banking interface is
	 * open, so the next open re-primes from a fresh baseline (opening a bank is not a deposit).
	 */
	private void trackBankMoves()
	{
		if (!config.trackRealisedGp() || !bankInterfaceOpen())
		{
			return;
		}
		if (prevBankInv == null)
		{
			prevBankInv = lastKnownInv;
			return;
		}
		final List<BankTracker.Move> moves = BankTracker.diff(prevBankInv, lastKnownInv);
		prevBankInv = lastKnownInv;
		if (moves.isEmpty())
		{
			return;
		}
		final boolean live = session != null && !sessionFinished;
		for (BankTracker.Move m : moves)
		{
			final long signed = m.isDeposit() ? m.getQty() : -m.getQty();
			if (live)
			{
				pendingBankMoves.add(new long[]{m.getItemId(), signed});
			}
			else
			{
				history.applyBankMove(m.getItemId(), signed, null, this::pushHistory);
			}
		}
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		if (!accruing())
		{
			return;
		}
		maybeIntendPickup(event);

		final String option = event.getMenuOption();
		if ("Eat".equals(option) || "Drink".equals(option))
		{
			handleConsumable(event);
			return;
		}
		handleSpell(event);
	}

	/** Arm the pickup tracker on a ground "Take" / telegrab; note a "Drop" so re-taking
	 *  your own item later isn't counted as income. */
	private void maybeIntendPickup(MenuOptionClicked event)
	{
		if (!config.trackPickups())
		{
			return;
		}
		final String option = event.getMenuOption();

		if ("Drop".equals(option) && event.getItemId() > 0)
		{
			dropIntent.put(event.getItemId(), client.getTickCount());
			return;
		}

		final MenuAction ma = event.getMenuAction();
		if (ma == null)
		{
			return;
		}
		final boolean take = "Take".equals(option)
			&& ma.getId() >= MenuAction.GROUND_ITEM_FIRST_OPTION.getId()
			&& ma.getId() <= MenuAction.GROUND_ITEM_FIFTH_OPTION.getId();
		if (take || ma == MenuAction.WIDGET_TARGET_ON_GROUND_ITEM)
		{
			pickupTracker.intend(event.getId(), client.getTickCount());
		}
	}

	/**
	 * Grows the current Slayer run's matched-mob set as new task NPCs spawn nearby. Reads
	 * {@link SlayerPluginService#getTargets()} - the bundled Slayer plugin already did the
	 * scene scan for its own highlighter, this just merges its result in - so this stays event
	 * driven rather than a per-tick scan.
	 */
	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		if (!config.trackSlayerTask() || !accruing() || !session.isSlayer())
		{
			return;
		}
		slayerTracker.accumulateTargets(slayerService);
	}

	@Subscribe
	public void onActorDeath(ActorDeath event)
	{
		if (!tracking())
		{
			return;
		}
		final Actor actor = event.getActor();
		if (actor instanceof NPC)
		{
			if (accruing())
			{
				handleNpcKill((NPC) actor);
			}
			return;
		}
		if (actor != client.getLocalPlayer())
		{
			return;
		}

		preDeathState = preDeathSnapshot();
		deathLossAcc.clear();
		deathGraveConfirmed = false;
		deathWindowTicks = DEATH_WINDOW_TICKS;

		pendingDeath = new DeathEntry(session.nextDeathId(), Instant.now(), Collections.emptyMap(), 0);
		pendingDeath.setMob(costMob());
		session.add(pendingDeath);
		pendings.put(pendingDeath.getId(), pendingDeath);
		accumulateDeathLoss();
		logger.line("death").put("deathId", pendingDeath.getId()).submit();
		refreshView();
	}

	/**
	 * An NPC died. A grouped run (Targeted farm or Slayer task) opens a per-kill bucket only
	 * for mobs matching its target group; a plain session bumps the per-mob kill tally (no
	 * bucket, no loot attribution). Either way a matched kill is counted against its mob name.
	 * (A chest-run label like "Moons of Peril" or "Barrows" is never one of {@code npc}'s real
	 * names, so this naturally never fires for one of those - see {@link #onLootReceived}.)
	 */
	private void handleNpcKill(NPC npc)
	{
		final String name = Text.removeTags(npc.getName() == null ? "" : npc.getName()).trim();
		if (name.isEmpty())
		{
			return;
		}

		// A phase-transition boss fires this event for its scripted death too (see
		// PHASE_DEATH_MOBS) - count it from the loot drop instead, in onLootReceived. Falls
		// through to normal counting when loot tracking is off and there is no drop to count.
		if (config.trackLoot() && isPhaseDeathMob(name))
		{
			return;
		}
		final int tick = client.getTickCount();

		if (!session.isGrouped())
		{
			if (tick - lastPlainKillTick < SAME_NPC_DEBOUNCE_TICKS && name.equals(lastPlainKillName))
			{
				return; // same ActorDeath double-fired
			}
			lastPlainKillTick = tick;
			lastPlainKillName = name;
			session.bumpKill(name);
			refreshView();
			return;
		}

		if (!session.matchesTarget(name, slayerTracker))
		{
			return;
		}
		final BossKill prev = lastKillByName.get(name);
		if (prev != null && tick - prev.getKillTick() < SAME_NPC_DEBOUNCE_TICKS)
		{
			return; // same ActorDeath double-fired
		}
		openKill(name, tick, "death");
		refreshView();
	}

	/** True when {@code npcName} is one of the {@link #PHASE_DEATH_MOBS}. */
	private static boolean isPhaseDeathMob(String npcName)
	{
		return npcName != null
			&& PHASE_DEATH_MOBS.contains(Text.removeTags(npcName).trim().toLowerCase(Locale.ROOT));
	}

	/** Note who the player is fighting, so a supply used mid-fight is charged to that mob. */
	private void trackOpponent()
	{
		final Player me = client.getLocalPlayer();
		final Actor foe = me == null ? null : me.getInteracting();
		if (foe instanceof NPC)
		{
			final String name = Text.removeTags(foe.getName() == null ? "" : foe.getName()).trim();
			if (!name.isEmpty())
			{
				currentOpponent = name;
				opponentTick = client.getTickCount();
			}
		}
	}

	/** The mob a cost incurred right now belongs to: whoever we are fighting (kept sticky a few
	 *  ticks past the last hit), else {@code null} (not in combat). A Targeted farm can have
	 *  several targets now, so - like Slayer - cost follows the actual opponent rather than
	 *  being forced onto one name; {@code perMobRollupMulti} folds anything that isn't one of
	 *  the farm's targets into the not-in-combat bucket. */
	private String costMob()
	{
		return currentOpponent != null
			&& client.getTickCount() - opponentTick <= OPPONENT_STICKY_TICKS
			? currentOpponent : null;
	}

	private BossKill openKill(String name, int tick, String source)
	{
		final BossKill k = session.addBossKill(name);
		k.setKillTick(tick);
		lastKillByName.put(name, k);
		session.bumpKill(name);
		logger.line("kill")
			.put("source", source)
			.put("mob", name)
			.put("count", session.getBossKills())
			.submit();
		return k;
	}

	/** Plain-session kill tally for a {@link #PHASE_DEATH_MOBS phase-transition boss}, driven
	 *  by its loot drop. Debounced against split loot events for the one kill. */
	private void bumpPhaseDeathKill(String source)
	{
		final String name = Text.removeTags(source).trim();
		final int tick = client.getTickCount();
		if (tick - lastPlainKillTick < LOOT_SAME_KILL_TICKS && name.equals(lastPlainKillName))
		{
			return;
		}
		lastPlainKillTick = tick;
		lastPlainKillName = name;
		session.bumpKill(name);
		logger.line("kill")
			.put("source", "loot")
			.put("mob", name)
			.put("count", session.getBossKills())
			.submit();
		refreshView();
	}

	// ------------------------------------------------------------------ income

	/**
	 * All loot RuneLite's loot tracker recognises - monster and boss kills, PvP kills,
	 * reward chests / caskets / minigame rewards, and pickpockets - arrives here already
	 * deduplicated. Needs the built-in Loot Tracker plugin enabled.
	 */
	@Subscribe
	public void onLootReceived(LootReceived event)
	{
		if (!accruing() || !config.trackLoot())
		{
			return;
		}
		final IncomeEvent.Type type = incomeType(event.getType());
		if (type == null)
		{
			return;
		}

		final Map<Integer, Integer> items = new LinkedHashMap<>();
		for (ItemStack is : event.getItems())
		{
			if (is.getId() > 0 && is.getQuantity() > 0)
			{
				items.merge(is.getId(), is.getQuantity(), Integer::sum);
			}
		}
		if (items.isEmpty())
		{
			return;
		}

		final String source = event.getName() == null || event.getName().isEmpty()
			? "Loot" : event.getName();
		final IncomeEvent ie = new IncomeEvent(type, Instant.now(), source, items);
		session.add(ie);
		// monster / PvP loot lands on the ground - watch for it entering the bag before it
		// counts toward net. Rewards and pickpockets go straight to the inventory (the
		// IncomeEvent marks itself fully collected).
		if (type == IncomeEvent.Type.NPC_LOOT || type == IncomeEvent.Type.PLAYER_LOOT)
		{
			lootCollector.add(ie, client.getTickCount());
		}

		// In a grouped run (Targeted farm or Slayer task), attribute matched-mob loot to the
		// kill it came from (if no matching kill fired an ActorDeath the loot itself opens the
		// kill). Everything else - stray mobs, and all loot in a plain session - stays in the
		// flat income list only.
		BossKill kill = null;
		if (type == IncomeEvent.Type.NPC_LOOT && session.isGrouped()
			&& session.matchesTarget(source, slayerTracker))
		{
			final String key = Text.removeTags(source).trim();
			final int tick = client.getTickCount();
			final BossKill match = lastKillByName.get(key);
			if (match != null && tick - match.getKillTick() <= LOOT_ATTRIBUTION_TICKS
				&& (match.getDrops().isEmpty() || tick - match.getKillTick() <= LOOT_SAME_KILL_TICKS))
			{
				kill = match;
			}
			else
			{
				kill = openKill(key, tick, "loot");
			}
			kill.add(ie);
		}
		else if (session.isGrouped())
		{
			// A shared reward chest (Barrows, Perilous Moons, a raid, ...) - see
			// CHEST_RUN_LABEL_BY_LOOT_NAME. The chest opening itself is the kill, one per loot
			// event, counted (and its loot attributed) only when the farm is actually targeting
			// that label - anything else stays stray, un-netted income.
			final String label = CHEST_RUN_LABEL_BY_LOOT_NAME.get(
				Text.removeTags(source).trim().toLowerCase(Locale.ROOT));
			if (label != null && session.matchesTarget(label, slayerTracker))
			{
				kill = openKill(label, client.getTickCount(), "chest");
				kill.add(ie);
			}
		}
		else if (type == IncomeEvent.Type.NPC_LOOT && !session.isGrouped() && isPhaseDeathMob(source))
		{
			// handleNpcKill ignores this boss's scripted death and a plain session has no loot
			// bucket to hang the count on - so count the kill here, off the drop.
			bumpPhaseDeathKill(source);
		}

		logger.line("loot")
			.put("kind", type.name())
			.put("source", source)
			.put("kill", kill != null ? kill.getIndex() : null)
			.put("items", namedItems(items))
			.put("droppedGp", lootValue(items))
			.put("valuation", config.incomeValuation().name())
			.submit();
		refreshView();
	}

	private static IncomeEvent.Type incomeType(LootRecordType t)
	{
		if (t == null)
		{
			return null;
		}
		switch (t)
		{
			case NPC:
				return IncomeEvent.Type.NPC_LOOT;
			case PLAYER:
				return IncomeEvent.Type.PLAYER_LOOT;
			case EVENT:
				return IncomeEvent.Type.EVENT_LOOT;
			case PICKPOCKET:
				return IncomeEvent.Type.PICKPOCKET;
			default:
				return null;
		}
	}

	/** Move an inventory loss that followed a "Drop" click into the {@link #droppedOut} pool. */
	private void trackDrops(Map<Integer, Integer> losses)
	{
		final int tick = client.getTickCount();
		dropIntent.values().removeIf(t -> tick - t > DROP_INTENT_TTL_TICKS);
		if (dropIntent.isEmpty() || losses.isEmpty())
		{
			return;
		}
		losses.forEach((id, qty) ->
		{
			final Integer di = dropIntent.get(id);
			if (di != null && tick - di <= DROP_INTENT_TTL_TICKS)
			{
				droppedOut.merge(id, qty, Integer::sum);
				dropIntent.remove(id);
			}
		});
	}

	/**
	 * A tick's inventory gains, in order of preference: collected loot for a drop we are
	 * watching; then your own items coming back off the ground (not income); then - if you
	 * clicked Take - an orphan ground pickup (or a late collect of an older drop).
	 */
	private void reconcileIncome(Map<Integer, Integer> gains)
	{
		if (session == null)
		{
			return;
		}
		final int tick = client.getTickCount();
		boolean changed = lootCollector.correlate(gains, tick);

		// items the player dropped earlier are theirs coming back, not new income;
		// coins already booked as alch income are likewise not fresh loot
		absorb(gains, droppedOut);
		absorb(gains, alchCredited);

		if (config.trackPickups() && !gains.isEmpty())
		{
			final Set<Integer> excluded = new HashSet<>(ammoTracker.tracked());
			excluded.addAll(session.getAmmoStats().keySet());
			final Map<Integer, Integer> picked = pickupTracker.collect(gains, tick, excluded);
			if (!picked.isEmpty())
			{
				// a deliberate Take of something that dropped a while ago belongs to that drop
				changed |= lootCollector.collectViaClick(picked);
				if (!picked.isEmpty())
				{
					final IncomeEvent ie = new IncomeEvent(IncomeEvent.Type.PICKUP, Instant.now(), "Ground", picked);
					session.add(ie);
					logger.line("loot")
						.put("kind", "PICKUP")
						.put("source", "Ground")
						.put("items", namedItems(picked))
						.put("droppedGp", lootValue(picked))
						.put("valuation", config.incomeValuation().name())
						.submit();
					changed = true;
				}
			}
		}

		if (changed)
		{
			viewDirty = true;
		}
	}

	/** Draw {@code gains} down against a "not new income" pool (dropped items back, alch coins). */
	private static void absorb(Map<Integer, Integer> gains, Map<Integer, Integer> pool)
	{
		if (pool.isEmpty())
		{
			return;
		}
		gains.entrySet().removeIf(g ->
		{
			final Integer out = pool.get(g.getKey());
			if (out == null || out <= 0)
			{
				return false;
			}
			final int take = Math.min(g.getValue(), out);
			pool.put(g.getKey(), out - take);
			g.setValue(g.getValue() - take);
			return g.getValue() <= 0;
		});
	}

	// ------------------------------------------------------------------ skilling

	/** Rune item ids - never a skilling material (a manual cast already books its runes, and
	 *  no skilling method consumes a rune), so they are kept out of skilling attribution. */
	private static final Set<Integer> RUNE_ITEM_IDS;

	static
	{
		final Set<Integer> ids = new HashSet<>();
		for (Rune r : Rune.values())
		{
			ids.add(r.getItemId());
		}
		RUNE_ITEM_IDS = Collections.unmodifiableSet(ids);
	}

	/**
	 * Plain-session only: on a tick a tracked non-combat skill gained XP, book the inventory /
	 * worn / rune-pouch movement the loot / pickup / drop logic left behind as that skill's
	 * product (in) and materials (out). {@code gains} has already been drawn down by
	 * {@link #reconcileIncome}; {@code losses} is this tick's raw shrinkage.
	 */
	private void reconcileSkilling(Map<Integer, Integer> gains, Map<Integer, Integer> losses)
	{
		if (session == null || session.isGrouped())
		{
			return;
		}
		final Skill skill = skillingTracker.activeSkill(client.getTickCount());
		if (skill == null)
		{
			return;
		}
		final String src = skill.getName();

		final Map<Integer, Integer> products = new LinkedHashMap<>();
		gains.forEach((id, qty) ->
		{
			if (qty > 0 && !isSkillingExcluded(id))
			{
				products.merge(id, qty, Integer::sum);
			}
		});

		final Map<Integer, Integer> materials = new LinkedHashMap<>();
		losses.forEach((id, qty) ->
		{
			// a pending manual "Drop" of this id is the drop tracker's, not a skilling material
			if (qty > 0 && !dropIntent.containsKey(id) && !isSkillingExcluded(id))
			{
				materials.merge(id, qty, Integer::sum);
			}
		});

		if (products.isEmpty() && materials.isEmpty())
		{
			return;
		}

		long productGp = 0;
		if (!products.isEmpty())
		{
			session.add(new IncomeEvent(IncomeEvent.Type.SKILLING, Instant.now(), src, products));
			productGp = lootValue(products);
		}

		long materialGp = 0;
		for (Map.Entry<Integer, Integer> e : materials.entrySet())
		{
			final long gp = IncomeValuation.value(e.getKey(), e.getValue(),
				IncomeValuation.Mode.GE, priceLookup);
			session.add(new CostEvent(CostEvent.Type.SKILLING, Instant.now(),
				e.getKey(), e.getValue(), gp, itemName(e.getKey()), null));
			// attribute to the skill name (not costMob()) so History merges gained + cost into
			// one row and costByMob still totals to Session#total()
			session.addMobCost(src, gp);
			materialGp += gp;
		}

		logger.line("skilling")
			.put("skill", src)
			.put("products", products.isEmpty() ? null : namedItems(products))
			.put("productGp", productGp)
			.put("materials", materials.isEmpty() ? null : namedItems(materials))
			.put("materialGp", materialGp)
			.submit();
		viewDirty = true;
	}

	/**
	 * Ids kept out of skilling attribution: runes (a manual cast books them; no skilling
	 * method consumes a rune), ammo this session has actually fired (its fired / recovered
	 * tally owns that id - so fletching darts you're also shooting doesn't double up, but
	 * smithing cannonballs you never fire still counts), and teleport tablets. Everything
	 * else - including ammo you make but don't fire - is fair game.
	 */
	private boolean isSkillingExcluded(int id)
	{
		return RUNE_ITEM_IDS.contains(id)
			|| session.getAmmoStats().containsKey(id)
			|| isTeleportTab(id);
	}

	private long lootValue(Map<Integer, Integer> items)
	{
		return IncomeValuation.value(items, config.incomeValuation(), priceLookup);
	}

	private long lootValue(int itemId, int qty)
	{
		return IncomeValuation.value(itemId, qty, config.incomeValuation(), priceLookup);
	}

	/** The map that counts toward profit for this event - normally what was collected, or
	 *  everything that dropped when {@code countUncollectedDrops} is on. */
	private Map<Integer, Integer> countedItems(IncomeEvent e)
	{
		return config.countUncollectedDrops() ? e.getItems() : e.getCollected();
	}

	/** Value that actually counts toward net, after the hide-below-N filter. */
	private long collectedTotal()
	{
		return incomeTotal(this::countedItems);
	}

	/** Value of everything that dropped (collected or not), after the hide filter. */
	private long potentialTotal()
	{
		return incomeTotal(IncomeEvent::getItems);
	}

	private long incomeTotal(java.util.function.Function<IncomeEvent, Map<Integer, Integer>> map)
	{
		if (session == null)
		{
			return 0L;
		}
		final long floor = Math.max(0, config.ignoreIncomeBelow());
		long total = 0L;
		for (IncomeEvent e : session.getIncome())
		{
			if (lootValue(e.getItems()) < floor)
			{
				continue;
			}
			total += lootValue(map.apply(e));
		}
		return total;
	}

	/** Records, per item, the largest shortfall vs the pre-death kit seen so far. Runs on
	 *  every container change and every tick during the death window, so a near-instant
	 *  grave reclaim still leaves a trace. */
	private void accumulateDeathLoss()
	{
		final Map<Integer, Integer> current = ContainerSnapshot.union(lastKnownInv, lastKnownWorn);
		preDeathState.forEach((id, preQty) ->
		{
			final int missing = preQty - current.getOrDefault(id, 0);
			if (missing > deathLossAcc.getOrDefault(id, 0))
			{
				deathLossAcc.put(id, missing);
			}
		});
	}

	private void finalizeDeath()
	{
		final DeathEntry e = pendingDeath;
		pendingDeath = null;
		if (e == null || e.getState() != DeathEntry.State.PENDING)
		{
			return;
		}

		// ammo lost to the death is the death handler's to price - snap the ammo baseline
		// past it so a later reclaim doesn't read as a restock and the drop isn't double-charged
		ammoTracker.reconcile(ammoOwned(), false);

		final Map<Integer, Integer> lost = new HashMap<>();
		deathLossAcc.forEach((id, qty) ->
		{
			if (qty > 0)
			{
				lost.put(id, qty);
			}
		});

		// grave message but we never caught the container dip -> assume the whole kit went in
		if (lost.isEmpty() && deathGraveConfirmed)
		{
			lost.putAll(preDeathState);
		}

		if (lost.isEmpty())
		{
			logger.line("death_no_loss")
				.put("deathId", e.getId())
				.put("preDeathItems", preDeathState.size())
				.submit();
			refreshView();
			return;
		}

		final long full = deathCostService.geValue(lost);
		e.setLoss(lost, full);
		e.setEstimatedFee(deathCostService.graveFeeEstimate(lost, isIronman()));
		logger.line("death_pending")
			.put("deathId", e.getId())
			.put("fullValue", full)
			.put("estimatedFee", e.getEstimatedFee())
			.put("items", namedItems(lost))
			.submit();

		// a reclaim may already have happened while the window was open
		if (recentReclaimFeeTick >= 0 && client.getTickCount() - recentReclaimFeeTick <= DEATH_WINDOW_TICKS)
		{
			applyReclaim(e, recentReclaimFee);
		}
		refreshView();
	}

	/** A "retrieved from gravestone / Death's Office" line fired - resolve the oldest
	 *  still-pending death with whatever reclaim fee we last saw in chat. */
	private void resolveOldestPendingFromReclaim()
	{
		// a retrieval line means a grave existed - let finalizeDeath fall back to the full
		// kit if it never managed to catch the container dip
		deathGraveConfirmed = true;
		if (deathWindowTicks > 0)
		{
			deathWindowTicks = 0;
			finalizeDeath();
		}
		for (DeathEntry e : pendings.values())
		{
			if (e.getState() == DeathEntry.State.PENDING && !e.getLostItems().isEmpty())
			{
				final long fee = (recentReclaimFeeTick >= 0
					&& client.getTickCount() - recentReclaimFeeTick <= DEATH_WINDOW_TICKS)
					? recentReclaimFee : 0L;
				applyReclaim(e, fee);
				break;
			}
		}
		recentReclaimFee = -1;
		recentReclaimFeeTick = -1;
	}

	private void applyReclaim(DeathEntry e, long fee)
	{
		e.setState(DeathEntry.State.RETURNED);
		e.setResolvedCost(Math.max(0, fee));
		e.setEstimatedFee(Math.max(0, fee));
		e.setUserConfirmed(true);
		logResolved(e, "reclaimed");
		refreshView();
	}

	/** Container-diff fallback: items visibly back but no chat resolution seen. */
	private void checkContainerReturn()
	{
		if (pendings.isEmpty())
		{
			return;
		}
		final Map<Integer, Integer> current = ContainerSnapshot.union(lastKnownInv, lastKnownWorn);
		boolean changed = false;
		for (DeathEntry e : pendings.values())
		{
			if (e.getState() != DeathEntry.State.PENDING || e.getLostItems().isEmpty())
			{
				continue;
			}
			if (!ContainerSnapshot.covers(current, e.getLostItems()))
			{
				continue;
			}
			e.setState(DeathEntry.State.RETURNED);
			e.setEstimatedFee(deathCostService.graveFeeEstimate(e.getLostItems(), isIronman()));
			e.setUserConfirmed(false);
			logger.line("death_returned")
				.put("deathId", e.getId())
				.put("via", "container")
				.put("estimatedFee", e.getEstimatedFee())
				.submit();
			changed = true;
		}
		if (changed)
		{
			refreshView();
		}
	}

	private boolean isIronman()
	{
		// VarbitID.IRONMAN: 0 normal, 1 IM, 2 UIM, 3 HCIM, 4 GIM, 5 HC GIM - all get the fee discount
		return client.getVarbitValue(VarbitID.IRONMAN) > 0;
	}

	/**
	 * An "Eat"/"Drink" click. Doesn't charge anything on its own - a held click fires this many
	 * times but the game only consumes one dose / bite per 3 ticks. It just arms
	 * {@link #chargeConsumed}, which books the cost when (and only when) the food / potion
	 * actually leaves the inventory.
	 */
	private void handleConsumable(MenuOptionClicked event)
	{
		int itemId = event.getItemId();
		if (itemId <= 0)
		{
			final Widget widget = event.getWidget();
			if (widget != null)
			{
				itemId = widget.getItemId();
			}
		}
		// only arm for something the pricer actually recognises as a consumable, so a stray
		// "Eat"/"Drink"-labelled action on some other item can't charge an unrelated drop
		if (consumableCostService.price(itemId, false) == null)
		{
			return;
		}
		consumeArmedTick = client.getTickCount();
	}

	/**
	 * Book the real cost of a consumable that just left the inventory, if an "Eat"/"Drink" click
	 * armed it within the last {@link #CONSUME_CONFIRM_TICKS} ticks. Charges once per unit that
	 * actually went (a potion sip is one unit: the "(4)" id drops and the "(3)" id appears, so
	 * the clicked id shows up in {@code losses} exactly once). Removes the consumed item from
	 * {@code losses}, and the lower-dose potion it became from {@code gains}, so the drop /
	 * skilling / income logic downstream can't also claim either side.
	 */
	private void chargeConsumed(Map<Integer, Integer> losses, Map<Integer, Integer> gains)
	{
		if (losses.isEmpty() || client.getTickCount() - consumeArmedTick > CONSUME_CONFIRM_TICKS)
		{
			return;
		}
		boolean any = false;
		final java.util.Iterator<Map.Entry<Integer, Integer>> it = losses.entrySet().iterator();
		while (it.hasNext())
		{
			final Map.Entry<Integer, Integer> e = it.next();
			final int lostId = e.getKey();
			final ConsumableCostService.Consumed c =
				consumableCostService.price(lostId, config.potionDoseAware());
			if (c == null)
			{
				continue;
			}
			final int qty = Math.max(1, e.getValue());
			for (int i = 0; i < qty; i++)
			{
				session.add(new CostEvent(CostEvent.Type.CONSUMABLE, Instant.now(),
					c.getItemId(), 1, c.getGp(), c.getName(), null));
				session.addMobCost(costMob(), c.getGp());
			}
			logger.line("consumable")
				.put("itemId", c.getItemId())
				.put("item", c.getName())
				.put("qty", qty)
				.put("gp", c.getGp() * (long) qty)
				.submit();
			it.remove();
			// the sip turned a "(4)" into a "(3)" - that lower dose is the same potion, not income
			final int family = ItemVariationMapping.map(lostId);
			gains.keySet().removeIf(g -> ItemVariationMapping.map(g) == family);
			any = true;
		}
		if (any)
		{
			// this consume cycle is paid for - a held click re-arms on its next MenuOptionClicked
			consumeArmedTick = -1000;
			refreshView();
		}
	}

	// ------------------------------------------------------------------ ammo

	/** Every ammo item id the plugin can see a quantity for, and that quantity. */
	private Map<Integer, Long> ammoOwned()
	{
		final Map<Integer, Long> owned = new HashMap<>();

		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn != null)
		{
			addSlotAmmo(owned, worn.getItem(AMMO_SLOT), false);
			addSlotAmmo(owned, worn.getItem(WEAPON_SLOT), true);
		}

		// Inventory copies of anything already tracked, so unequipping ammo to swap types nets
		// to zero instead of reading as a full-stack loss. Cannonballs are folded into this same
		// set (rather than a second loop) specifically so each id is only ever added to `owned`
		// once - a second loop using the same `owned.merge(id, inv, ...)` pattern would double
		// whatever this one already added the moment cannonballs became part of `tracked()`
		// (i.e. from the tick after they were first seen onward), which is exactly what caused
		// loading the cannon to charge double.
		//
		// Cannonballs are tracked purely by inventory count, like any other ammo - the cannon's
		// internal loaded-count varp is deliberately not consulted: combining the two (inventory
		// + loaded) was meant to make "load into cannon" a wash, but the two updates don't
		// reliably land in the same tick during a multi-ball load animation, so it was instead
		// charging once when the count visibly dipped mid-load and again when the cannon
		// actually fired. Charging purely off the inventory drop means loading is the one and
		// only charge; the cannon firing later never touches the inventory, so it can't charge
		// again. If unfired balls ever come back to the inventory (reclaiming the cannon),
		// that's an ordinary inventory rise and the tracker already treats it as a recovery, the
		// same as picking arrows back up off the ground.
		final Set<Integer> invTracked = new HashSet<>(ammoTracker.tracked());
		for (int cb : CANNONBALL_IDS)
		{
			invTracked.add(cb);
		}
		for (int id : invTracked)
		{
			final long inv = lastKnownInv.getOrDefault(id, 0);
			if (inv > 0)
			{
				owned.merge(id, inv, Long::sum);
			}
		}

		// Dizana's quiver
		final int quiverId = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO);
		final int quiverQty = client.getVarpValue(VarPlayerID.DIZANAS_QUIVER_TEMP_AMMO_AMOUNT);
		if (quiverId > 0 && quiverQty > 0)
		{
			owned.merge(quiverId, (long) quiverQty, Long::sum);
		}

		return owned;
	}

	private void addSlotAmmo(Map<Integer, Long> owned, Item item, boolean stackableOnly)
	{
		if (item == null || item.getId() <= 0 || item.getQuantity() <= 0)
		{
			return;
		}
		if (stackableOnly)
		{
			final ItemComposition comp = itemManager.getItemComposition(item.getId());
			if (comp == null || !comp.isStackable())
			{
				return;
			}
		}
		owned.merge(item.getId(), (long) item.getQuantity(), Long::sum);
	}

	/** {@code {itemId, quantity}} of whatever is in the equipped weapon slot, or {@code null}
	 *  when the slot is empty - fed to {@link #blueMoonFreeze}. */
	private long[] weaponSlotItem()
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final Item w = worn == null ? null : worn.getItem(WEAPON_SLOT);
		return w == null || w.getId() <= 0 || w.getQuantity() <= 0
			? null : new long[]{w.getId(), w.getQuantity()};
	}

	private void reconcileAmmo(boolean accrue)
	{
		if (session == null)
		{
			return;
		}
		// always reconcile so the baseline stays current; only charge when tracking is on
		// and not paused (death window / bank open)
		final boolean moved = ammoTracker.reconcile(ammoOwned(), accrue && config.trackAmmo());
		if (!moved)
		{
			return;
		}
		final Map<Integer, long[]> stats = ammoTracker.stats();
		long gp = 0;
		for (Map.Entry<Integer, long[]> e : stats.entrySet())
		{
			gp += e.getValue()[2] * Math.max(0, itemManager.getItemPrice(e.getKey()));
		}
		session.setAmmo(stats, gp);
		// charge the growth in ammo spend to whoever is being shot at
		session.addMobCost(costMob(), gp - ammoGpCharged);
		ammoGpCharged = gp;
		viewDirty = true;
	}

	// ------------------------------------------------------------------ charged weapons

	/** True when {@code weapon} is the item in the weapon slot right now. */
	private boolean isWielding(ChargedWeapon weapon)
	{
		final ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		final Item w = worn == null ? null : worn.getItem(WEAPON_SLOT);
		return w != null && w.getId() > 0 && weapon.isWeaponItem(w.getId());
	}

	/** One attack with {@code weapon} = one charge spent; re-price the running total and
	 *  charge the growth to whoever is being fought. */
	private void recordChargedAttack(ChargedWeapon weapon)
	{
		if (session == null || !chargedWeaponTracker.recordAttack(weapon, client.getTickCount()))
		{
			return;
		}
		final Map<ChargedWeapon, Long> spent = chargedWeaponTracker.spent();
		long gp = 0;
		for (Map.Entry<ChargedWeapon, Long> e : spent.entrySet())
		{
			gp += e.getKey().cost(e.getValue(), priceLookup::ge);
		}
		session.setChargedWeapons(spent, gp);
		session.addMobCost(costMob(), gp - chargedWeaponGpCharged);
		chargedWeaponGpCharged = gp;
		viewDirty = true;
	}

	// ------------------------------------------------------------------ teleports

	private Map<Integer, Integer> buildTeleChargeMap()
	{
		final Map<Integer, Integer> m = new HashMap<>();
		for (int id : TeleportCharges.variantIds())
		{
			final ItemComposition comp = itemManager.getItemComposition(id);
			m.put(id, comp != null ? parseCharges(comp.getName()) : 0);
		}
		return m;
	}

	/**
	 * group base -&gt; gp of one charge, taken from the highest-charge variant that actually
	 * has a GE price. Used when a specific charge tier is untradeable (glory(5)/(6)) so the
	 * marginal price would come out zero.
	 */
	private Map<Integer, Long> buildTelePerChargeCost()
	{
		final Map<Integer, Long> perCharge = new HashMap<>();
		TeleportCharges.groups().forEach((base, variants) ->
		{
			int bestCharges = 0;
			long best = 0;
			for (int id : variants)
			{
				final int ch = teleChargesById.getOrDefault(id, 0);
				final long price = Math.max(0, itemManager.getItemPrice(id));
				if (ch > 0 && price > 0 && ch >= bestCharges)
				{
					bestCharges = ch;
					best = price / ch;
				}
			}
			if (best > 0)
			{
				perCharge.put(base, best);
			}
		});
		return perCharge;
	}

	private static int parseCharges(String name)
	{
		final Matcher m = CHARGE_SUFFIX.matcher(name);
		return m.find() ? Integer.parseInt(m.group(1)) : 0;
	}

	private void detectTeleports(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		if (!config.trackTeleports() || session == null || before.equals(after))
		{
			return;
		}
		boolean changed = false;

		for (TeleportCharges.Charge c : TeleportCharges.detect(before, after, teleChargesById))
		{
			final long gp = teleportCost(c);
			final String label = teleportLabel(c);
			session.add(new CostEvent(CostEvent.Type.TELEPORT, Instant.now(),
				c.getFromId(), (int) c.getChargesUsed(), gp, label, null));
			session.addMobCost(costMob(), gp);
			logger.line("teleport")
				.put("item", label)
				.put("charges", c.getChargesUsed())
				.put("gp", gp)
				.submit();
			changed = true;
		}

		// teleport tablets / scrolls: a stackable "* teleport" item that left the inventory
		for (Map.Entry<Integer, Integer> e : before.entrySet())
		{
			final int id = e.getKey();
			final int used = e.getValue() - after.getOrDefault(id, 0);
			if (used <= 0 || used > 3 || !isTeleportTab(id))
			{
				continue;
			}
			final String name = itemName(id);
			final long gp = Math.max(0, itemManager.getItemPrice(id)) * used;
			session.add(new CostEvent(CostEvent.Type.TELEPORT, Instant.now(),
				id, used, gp, name, null));
			session.addMobCost(costMob(), gp);
			logger.line("teleport")
				.put("itemId", id)
				.put("item", name)
				.put("qty", used)
				.put("gp", gp)
				.submit();
			changed = true;
		}

		if (changed)
		{
			refreshView();
		}
	}

	private boolean isTeleportTab(int id)
	{
		return teleTabCache.computeIfAbsent(id, k ->
		{
			final ItemComposition comp = itemManager.getItemComposition(k);
			return comp != null
				&& comp.isStackable()
				&& comp.getName().toLowerCase().contains("teleport");
		});
	}

	/**
	 * Marginal GE price of the charges used - {@code price(from) - price(to)} - when both
	 * tiers are tradeable; otherwise the per-charge fallback (untradeable glory(5)/(6) etc).
	 */
	private long teleportCost(TeleportCharges.Charge c)
	{
		final long fromPrice = Math.max(0, itemManager.getItemPrice(c.getFromId()));
		final long toPrice = c.getToId() > 0 ? Math.max(0, itemManager.getItemPrice(c.getToId())) : 0;
		if (fromPrice > 0 && (c.getToId() < 0 || toPrice > 0) && fromPrice >= toPrice)
		{
			return fromPrice - toPrice;
		}
		return teleCostPerCharge.getOrDefault(c.getBase(), 0L) * c.getChargesUsed();
	}

	private String teleportLabel(TeleportCharges.Charge c)
	{
		final String base = itemName(c.getBase()).replaceAll("\\s*\\(\\d+\\)\\s*$", "");
		final int from = teleChargesById.getOrDefault(c.getFromId(), 0);
		final int to = c.getToId() > 0 ? teleChargesById.getOrDefault(c.getToId(), 0) : 0;
		return base + " (" + from + "→" + to + ")";
	}

	private void handleSpell(MenuOptionClicked event)
	{
		final MenuAction action = event.getMenuAction();
		if (action == null)
		{
			return;
		}
		final int param1 = event.getParam1();

		if ("Cast".equals(event.getMenuOption())
			&& action != MenuAction.WIDGET_TARGET
			&& WidgetUtil.componentToInterface(param1) == InterfaceID.MAGIC_SPELLBOOK)
		{
			recordCast(param1, -1);
			return;
		}

		switch (action)
		{
			case WIDGET_TARGET_ON_NPC:
			case WIDGET_TARGET_ON_PLAYER:
			case WIDGET_TARGET_ON_GAME_OBJECT:
			case WIDGET_TARGET_ON_GROUND_ITEM:
			case WIDGET_TARGET_ON_WIDGET:
				final Widget selected = client.getSelectedWidget();
				if (selected != null
					&& WidgetUtil.componentToInterface(selected.getId()) == InterfaceID.MAGIC_SPELLBOOK)
				{
					recordCast(selected.getId(), spellTargetItem(event));
				}
				break;
			default:
				break;
		}
	}

	/** The inventory item a targeted spell was cast on (for High Alchemy), or -1. */
	private static int spellTargetItem(MenuOptionClicked event)
	{
		final Widget w = event.getWidget();
		int id = w != null ? w.getItemId() : -1;
		if (id <= 0)
		{
			id = event.getItemId();
		}
		return id;
	}

	private void recordCast(int componentId, int targetItemId)
	{
		final Spell spell = Spell.byComponent(componentId);
		if (spell == null)
		{
			return;
		}
		final int tick = client.getTickCount();
		if (tick == lastCastTick && componentId == lastCastComponent)
		{
			return;
		}
		lastCastTick = tick;
		lastCastComponent = componentId;

		final SpellCostService.Priced priced = spellCostService.price(spell);
		session.add(new CostEvent(CostEvent.Type.SPELL, Instant.now(),
			-1, 1, priced.getGp(), spell.getDisplayName(), priced.getBreakdown()));
		session.addMobCost(costMob(), priced.getGp());
		final Map<Integer, Integer> runeIds = new HashMap<>();
		priced.getRunesUsed().forEach((r, q) -> runeIds.merge(r.getItemId(), q, Integer::sum));
		session.addRunes(runeIds);

		if (spell == Spell.HIGH_ALCHEMY && targetItemId > 0)
		{
			recordAlchIncome(targetItemId);
		}
		logger.line("spell_cast")
			.put("spell", spell.getDisplayName())
			.put("gp", priced.getGp())
			.put("runes", priced.getBreakdown())
			.submit();
		refreshView();
	}

	/**
	 * A High Alchemy cast on a looted item. Under the potential / realised model this is a
	 * <b>realisation</b> event, not fresh income: the item is dropped from the run's potential
	 * ("gained") rollup and its HA coin value is recorded as realised at Stop (see
	 * {@link SessionHistory#applyAlch}). {@link #alchCredited} still keeps the coins out of
	 * the inventory-gain path.
	 */
	private void recordAlchIncome(int itemId)
	{
		final long coins = haValue(itemId);
		if (coins <= 0 || itemId == ItemID.COINS)
		{
			return;
		}
		session.addAlchedItem(itemId, 1);
		pendingAlch.add(new long[]{itemId, coins});
		pendingAlchMob.add(costMob());
		alchCredited.merge(ItemID.COINS, (int) coins, Integer::sum);
		logger.line("alch")
			.put("mob", costMob())
			.put("item", itemName(itemId))
			.put("haGp", coins)
			.submit();
		refreshView();
	}

	/** High Alchemy coin value of {@code id} (following a note to its real item), or 0. */
	private long haValue(int id)
	{
		try
		{
			final ItemComposition c = itemManager.getItemComposition(id);
			if (c == null)
			{
				return 0;
			}
			if (c.getNote() == 799 && c.getLinkedNoteId() != -1)
			{
				final ItemComposition real = itemManager.getItemComposition(c.getLinkedNoteId());
				return real == null ? 0 : Math.max(0, real.getHaPrice());
			}
			return Math.max(0, c.getHaPrice());
		}
		catch (RuntimeException ex)
		{
			return 0;
		}
	}

	// ------------------------------------------------------------------ view / helpers

	boolean isSessionActive()
	{
		return session != null && !sessionFinished;
	}

	/** How long the "no session" reminder stays suppressed after the bank / deposit box closes,
	 *  so it doesn't flicker on and off while you sort your inventory at a booth. */
	private static final long BANK_GRACE_MS = 3000;
	private long bankInterfaceSeenAt;

	/**
	 * Gate for the {@link NoSessionOverlay} "no session" reminder: nothing is being tracked
	 * and the player is out in the world. Suppressed at a bank / deposit box (and for a few
	 * seconds after it closes), within {@link #BANK_NEARBY_TILES} of a bank booth / chest /
	 * banker, at the Grand Exchange, and inside a player-owned house - all ordinary places to
	 * be standing around before a trip.
	 */
	boolean shouldWarnNoSession()
	{
		if (isSessionActive() || client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		final Player local = client.getLocalPlayer();
		final LocalPoint loc = local == null ? null : local.getLocalLocation();
		if (loc == null)
		{
			return false;
		}
		if (client.getWidget(InterfaceID.Bankmain.ITEMS) != null
			|| client.getWidget(InterfaceID.BankDepositbox.INVENTORY) != null)
		{
			bankInterfaceSeenAt = System.currentTimeMillis();
			return false;
		}
		if (System.currentTimeMillis() - bankInterfaceSeenAt < BANK_GRACE_MS)
		{
			return false;
		}
		final int region = WorldPoint.fromLocalInstance(client, loc).getRegionID();
		if (region == GRAND_EXCHANGE_REGION || POH_REGIONS.contains(region))
		{
			return false;
		}
		return !nearBank(local.getWorldLocation());
	}

	/** Any tracked bank booth / chest / banker within {@link #BANK_NEARBY_TILES} of {@code here}. */
	private boolean nearBank(WorldPoint here)
	{
		for (WorldPoint b : bankTiles)
		{
			if (b.getPlane() == here.getPlane() && b.distanceTo2D(here) <= BANK_NEARBY_TILES)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Rebuilds {@link #bankTiles} from the loaded scene (current plane) - bank booths / chests
	 * and any banker NPCs. Runs once per region load off {@link #bankScanQueued}, never per
	 * frame, so the reminder's proximity check stays a cheap walk of a handful of points.
	 */
	private void scanNearbyBanks()
	{
		bankTiles.clear();
		final WorldView wv = client.getTopLevelWorldView();
		if (client.getGameState() != GameState.LOGGED_IN || wv == null || wv.getScene() == null)
		{
			return;
		}
		final Tile[][] plane = wv.getScene().getTiles()[wv.getPlane()];
		for (Tile[] col : plane)
		{
			for (Tile tile : col)
			{
				if (tile == null)
				{
					continue;
				}
				for (GameObject go : tile.getGameObjects())
				{
					if (go != null && isBankObject(go.getId()))
					{
						bankTiles.add(tile.getWorldLocation());
						break;
					}
				}
			}
		}
		for (NPC npc : wv.npcs())
		{
			if (isBanker(npc))
			{
				bankTiles.add(npc.getWorldLocation());
			}
		}
	}

	/** True for a bank booth / chest / table / deposit box. Result cached per object id (bank
	 *  locs aren't varbit-swapped between bank and non-bank), so this decodes each id once. */
	private boolean isBankObject(int id)
	{
		final Boolean cached = bankObjectIdCache.get(id);
		if (cached != null)
		{
			return cached;
		}
		ObjectComposition comp = client.getObjectDefinition(id);
		final boolean multiloc = comp != null && comp.getImpostorIds() != null;
		if (multiloc && comp.getImpostor() != null)
		{
			comp = comp.getImpostor();
		}
		boolean bank = false;
		if (comp != null && comp.getActions() != null)
		{
			final String name = comp.getName();
			final boolean named = name != null && name.toLowerCase(Locale.ROOT).contains("bank");
			for (String a : comp.getActions())
			{
				if ("Bank".equals(a) || (named && ("Use".equals(a) || "Deposit".equals(a))))
				{
					bank = true;
					break;
				}
			}
		}
		if (!multiloc)
		{
			bankObjectIdCache.put(id, bank);
		}
		return bank;
	}

	private static boolean isBanker(NPC npc)
	{
		final NPCComposition c = npc == null ? null : npc.getTransformedComposition();
		if (c == null || c.getActions() == null)
		{
			return false;
		}
		for (String a : c.getActions())
		{
			if ("Bank".equals(a))
			{
				return true;
			}
		}
		return false;
	}

	ProfitLossCalculatorPanel.View currentView()
	{
		return currentView;
	}

	private void refreshView()
	{
		final ProfitLossCalculatorPanel.View view = buildView();
		if (view.equals(currentView))
		{
			return;
		}
		currentView = view;
		final ProfitLossCalculatorPanel p = panel;
		if (p != null)
		{
			SwingUtilities.invokeLater(() -> p.render(view));
		}
	}

	private static final DateTimeFormatter LINE_TIME =
		DateTimeFormatter.ofPattern("HH:mm:ss").withZone(ZoneId.systemDefault());

	private static final DateTimeFormatter SESSION_ID =
		DateTimeFormatter.ofPattern("yyyyMMdd-HHmmss").withZone(ZoneId.systemDefault());

	private String sessionId()
	{
		return session == null ? null : SESSION_ID.format(session.getStartTime());
	}

	private ProfitLossCalculatorPanel.View buildView()
	{
		// a stopped session's numbers are locked in at session-end prices
		if (sessionFinished && frozenView != null)
		{
			return frozenView;
		}

		final ProfitLossCalculatorPanel.View.ViewBuilder b = ProfitLossCalculatorPanel.View.builder()
			.showIncomeList(config.showIncomeList())
			.showCostList(config.showCostList())
			.slayerTaskName(slayerTracker.getTaskName() == null ? "" : slayerTracker.getTaskName())
			.slayerTaskLocation(slayerTracker.getTaskLocation() == null ? "" : slayerTracker.getTaskLocation())
			.slayerInitialAmount(slayerTracker.getInitialAmount())
			.slayerRemainingAmount(slayerTracker.getRemainingAmount());

		if (session == null)
		{
			return b.build();
		}

		for (DeathEntry e : session.getDeaths())
		{
			if (e.getLostItems().isEmpty() || e.isCounted())
			{
				continue;
			}
			b.death(new ProfitLossCalculatorPanel.DeathRow(e.getId(),
				namedItemsText(e.getLostItems()), e.getEstimatedFee(), e.getFullValue(),
				e.getState() != DeathEntry.State.PENDING));
		}

		final boolean grouped = session.isGrouped();
		// loot attributed to a kill; in a grouped run (Targeted/Slayer) this is the target
		// group's loot, and only this counts toward net - everything else is "other income"
		final Set<IncomeEvent> inKill = killAttributed();

		final long cost = session.total();
		final long collectedAll = collectedTotal();
		final long farmCollected = grouped ? killAttributedValue(this::countedItems) : collectedAll;
		final long farmDropped = grouped ? killAttributedValue(IncomeEvent::getItems) : potentialTotal();
		final long net = farmCollected - cost;
		// actual net: swap the GE-snapshot value of loot you've since alched for the coins it
		// actually made. (collectedTotal still values alched loot at GE - that's the "potential"
		// figure - so subtract it back out here and add the realised proceeds instead.)
		final long actualNet = net + realisedSoFar() - alchedLootedGeValue();
		// the figure the rate / per-kill lines describe: the actual net once anything's been
		// cashed out this run, otherwise the potential net
		final long headlineNet = (realisedSoFar() > 0 || bankedSoFar() > 0) ? actualNet : net;
		final long kills = session.getBossKills();
		final long secs = java.time.Duration.between(session.getStartTime(),
			session.getEndTime() != null ? session.getEndTime() : Instant.now()).getSeconds();

		b.gainItems(gainGridItems(grouped ? inKill : null));
		b.lossItems(lossGridItems());
		b.incomeEvents(incomeLines(session, inKill));
		b.costEvents(eventLines(session));
		if (grouped)
		{
			b.killRows(killRows());
		}
		if (session.isTargeted())
		{
			b.mobBlocks(targetFarmMobBlocks());
		}

		return b
			.active(!sessionFinished)
			.paused(session.isPaused())
			.finished(sessionFinished)
			.mode(session.getMode())
			.state(sessionFinished ? "stopped" : session.isPaused() ? "paused" : "running")
			.title(sessionTitle())
			.kills((int) kills)
			.elapsedSeconds(secs)
			.gains(farmCollected)
			.losses(cost)
			.net(net)
			// once something's been cashed out, the rate / per-kill figure follows the actual net
			.netPerHour(secs > 60 ? headlineNet * 3600 / secs : 0)
			.gpPerKill(grouped && kills > 0 ? headlineNet / kills : 0)
			.secPerKill(grouped && kills > 0 && secs > 0 ? secs / kills : 0)
			.potential(farmDropped)
			.atRisk(session.atRiskTotal())
			.realisedSoFar(realisedSoFar())
			.bankedSoFar(bankedSoFar())
			.actualNet(actualNet)
			.build();
	}

	/** GE-snapshot value of loot that was looted this run and has since been High Alched - the
	 *  slice of {@link #collectedTotal()} that {@link #realisedSoFar()} has replaced with real
	 *  coins. Only the alched quantity that actually came from loot counts (alching an item you
	 *  brought yourself isn't in collectedTotal, so there's nothing to subtract). */
	private long alchedLootedGeValue()
	{
		if (session == null || session.getAlchedItems().isEmpty())
		{
			return 0L;
		}
		long v = 0L;
		for (Map.Entry<Integer, Integer> a : session.getAlchedItems().entrySet())
		{
			final int id = a.getKey();
			int collected = 0;
			for (IncomeEvent e : session.getIncome())
			{
				collected += e.getCollected().getOrDefault(id, 0);
			}
			final int fromLoot = Math.min(a.getValue(), collected);
			if (fromLoot > 0)
			{
				v += lootValue(id, fromLoot);
			}
		}
		return v;
	}

	/** HA coin value alched during this run so far - a live hint; the real realised total is
	 *  History-tab only (see {@link SessionHistory#applyAlch}). */
	private long realisedSoFar()
	{
		long gp = 0;
		for (long[] a : pendingAlch)
		{
			gp += a[1];
		}
		return gp;
	}

	/**
	 * Net GE-priced value of this run's <b>loot</b> moved to a bank / deposit box so far - a
	 * live hint. Capped per item at what has actually been collected this run (the same cap
	 * {@link SessionHistory#applyBankMove} applies), so shuffling unrelated supplies or gear at
	 * a bank mid-run never registers - only loot you've secured does.
	 */
	private long bankedSoFar()
	{
		if (session == null || pendingBankMoves.isEmpty())
		{
			return 0L;
		}
		// net signed qty moved per item id (deposits +, withdrawals −)
		final Map<Integer, Long> movedByItem = new HashMap<>();
		for (long[] mv : pendingBankMoves)
		{
			movedByItem.merge((int) mv[0], mv[1], Long::sum);
		}
		long gp = 0L;
		for (Map.Entry<Integer, Long> e : movedByItem.entrySet())
		{
			final int id = e.getKey();
			long collected = 0L;
			for (IncomeEvent ie : session.getIncome())
			{
				collected += ie.getCollected().getOrDefault(id, 0);
			}
			final long banked = Math.min(Math.max(0L, e.getValue()), collected);
			if (banked > 0)
			{
				gp += banked * Math.max(0, itemManager.getItemPrice(id));
			}
		}
		return gp;
	}

	/** The set of income events attributed to a kill bucket (identity-based). */
	private Set<IncomeEvent> killAttributed()
	{
		final Set<IncomeEvent> in = Collections.newSetFromMap(new java.util.IdentityHashMap<>());
		for (BossKill k : session.getKills())
		{
			in.addAll(k.getDrops());
		}
		return in;
	}

	/** Value of kill-attributed loot, priced by {@code map} (collected vs everything dropped),
	 *  after the hide-below-N filter. */
	private long killAttributedValue(java.util.function.Function<IncomeEvent, Map<Integer, Integer>> map)
	{
		final long floor = Math.max(0, config.ignoreIncomeBelow());
		long total = 0L;
		for (IncomeEvent e : killAttributed())
		{
			if (lootValue(e.getItems()) < floor)
			{
				continue;
			}
			total += lootValue(map.apply(e));
		}
		return total;
	}

	/**
	 * Per-mob rollup for the run - the shape written to history, and also reused live for the
	 * Targeted tab's per-mob blocks (see {@link #targetFarmMobBlocks}). Loot is grouped by the
	 * NPC that dropped it; costs and deaths by whoever was being fought when they were incurred
	 * (the empty-string key = incurred while not in combat). A Targeted farm keeps one row per
	 * matched target mob (everything else is dropped); a Slayer run keeps one row per matched
	 * species (non-task mobs are dropped, same scoping); a plain session keeps every mob it
	 * touched.
	 */
	private Map<String, RunRecord.MobRun> perMobRollup()
	{
		if (!session.isGrouped())
		{
			return perMobRollupMulti(mob -> true);
		}
		return perMobRollupMulti(mob -> mob.isEmpty() || session.matchesTarget(mob, slayerTracker));
	}

	/**
	 * One row per mob name actually touched. {@code keep} decides which mob names get their own
	 * row - always-true for a plain session, and "one of the farm's targets" / "task-matched"
	 * for Targeted / Slayer respectively (both funnel through {@link Session#matchesTarget}).
	 * Loot from a mob {@code keep} rejects is dropped entirely (it was never live-counted toward
	 * net either - see {@code killAttributed} in {@link #buildView}), but its cost/deaths fold
	 * into the not-in-combat bucket rather than vanishing, so the rollup's total cost still
	 * matches {@link Session#total()} - the figure the live Net is built from.
	 */
	private Map<String, RunRecord.MobRun> perMobRollupMulti(java.util.function.Predicate<String> keep)
	{
		final boolean full = config.countUncollectedDrops();
		final long floor = Math.max(0, config.ignoreIncomeBelow());
		final Map<String, RunRecord.MobRun> out = new LinkedHashMap<>();

		final Map<String, long[]> scalar = new LinkedHashMap<>();   // mob -> {kills, cost, deaths}
		final Map<String, Map<Integer, Integer>> got = new LinkedHashMap<>();
		final Map<String, Map<Integer, Integer>> drop = new LinkedHashMap<>();

		// an event bucketed into a BossKill belongs to that kill's mob regardless of its own
		// `source` label - a shared reward (e.g. Perilous Moons' Lunar Chest) is named after
		// the chest, not any one boss - so this rollup agrees with the live view's
		// killAttributed()/net instead of re-deriving attribution from the source string alone.
		final Map<IncomeEvent, String> killMobOf = new java.util.IdentityHashMap<>();
		for (BossKill k : session.getKills())
		{
			for (IncomeEvent d : k.getDrops())
			{
				killMobOf.put(d, k.getName());
			}
		}

		for (IncomeEvent e : session.getIncome())
		{
			if (e.getType() == IncomeEvent.Type.PICKUP)
			{
				continue; // ground pickups have no mob
			}
			final String mob = killMobOf.getOrDefault(e,
				Text.removeTags(e.getSource() == null ? "" : e.getSource()).trim());
			if (mob.isEmpty() || lootValue(e.getItems()) < floor || !keep.test(mob))
			{
				continue;
			}
			got.computeIfAbsent(mob, k -> new LinkedHashMap<>());
			(full ? e.getItems() : e.getCollected()).forEach((id, q) -> got.get(mob).merge(id, q, Integer::sum));
			drop.computeIfAbsent(mob, k -> new LinkedHashMap<>());
			e.getItems().forEach((id, q) -> drop.get(mob).merge(id, q, Integer::sum));
		}

		// a High Alched looted item is realised, not potential - drop it from "gained"
		final Map<Integer, Integer> alched = new HashMap<>(session.getAlchedItems());
		for (Map<Integer, Integer> mobItems : got.values())
		{
			for (Map.Entry<Integer, Integer> ae : alched.entrySet())
			{
				final Integer have = mobItems.get(ae.getKey());
				if (ae.getValue() <= 0 || have == null || have <= 0)
				{
					continue;
				}
				final int take = Math.min(have, ae.getValue());
				mobItems.put(ae.getKey(), have - take);
				ae.setValue(ae.getValue() - take);
			}
		}
		session.getKillsByMob().forEach((mob, n) ->
		{
			if (keep.test(mob))
			{
				scalar.computeIfAbsent(mob, k -> new long[3])[0] += n;
			}
		});
		session.getCostByMob().forEach((mob, gp) ->
			scalar.computeIfAbsent(keep.test(mob) ? mob : SessionHistory.UNATTRIBUTED, k -> new long[3])[1] += gp);
		for (DeathEntry d : session.getDeaths())
		{
			if (!d.isCounted())
			{
				continue;
			}
			final String rawMob = d.getMob() == null ? SessionHistory.UNATTRIBUTED : d.getMob();
			final String mob = keep.test(rawMob) ? rawMob : SessionHistory.UNATTRIBUTED;
			final long[] s = scalar.computeIfAbsent(mob, k -> new long[3]);
			s[1] += d.getResolvedCost();
			s[2] += 1;
		}

		final Set<String> keys = new java.util.LinkedHashSet<>();
		keys.addAll(got.keySet());
		keys.addAll(scalar.keySet());
		for (String key : keys)
		{
			final long[] s = scalar.getOrDefault(key, new long[3]);
			final List<long[]> items = itemTriples(got.getOrDefault(key, Collections.emptyMap()));
			final long gained = items.stream().mapToLong(t -> t[2]).sum();
			final long dropGp = drop.getOrDefault(key, Collections.emptyMap()).entrySet().stream()
				.mapToLong(en -> lootValue(en.getKey(), en.getValue())).sum();
			out.put(key, new RunRecord.MobRun((int) s[0], gained, dropGp, s[1], (int) s[2], items));
		}
		return out;
	}

	/** The most recent {@value #KILL_ROWS_SHOWN} kills of a Targeted farm or Slayer task,
	 *  newest first - index, time and that kill's collected value. A Slayer run's rows also
	 *  carry the mob name (several species can appear); Targeted leaves it blank as redundant. */
	private List<ProfitLossCalculatorPanel.KillRow> killRows()
	{
		final boolean full = config.countUncollectedDrops();
		final boolean showMobName = session.isSlayer() || session.getTargetMobs().size() > 1;
		final List<BossKill> kills = session.getKills();
		final List<ProfitLossCalculatorPanel.KillRow> out = new ArrayList<>();
		for (int i = kills.size() - 1; i >= 0 && out.size() < KILL_ROWS_SHOWN; i--)
		{
			final BossKill k = kills.get(i);
			long collected = 0;
			long dropped = 0;
			final Map<Integer, Integer> items = new LinkedHashMap<>();
			for (IncomeEvent e : k.getDrops())
			{
				collected += lootValue(full ? e.getItems() : e.getCollected());
				dropped += lootValue(e.getItems());
				(full ? e.getItems() : e.getCollected()).forEach((id, q) -> items.merge(id, q, Integer::sum));
			}
			final String tip = items.isEmpty() ? null
				: "<html>" + namedItemsText(items)
					+ (dropped != collected ? "<br>" + gp(collected) + " of " + gp(dropped) + " kept" : "")
					+ "</html>";
			out.add(new ProfitLossCalculatorPanel.KillRow(
				k.getIndex(), LINE_TIME.format(k.getTime()), collected, dropped, tip,
				showMobName ? k.getName() : ""));
		}
		return out;
	}

	private static final int KILL_ROWS_SHOWN = 60;

	/** Green grid: collected loot, valued the way loot is, sorted by value. When {@code only}
	 *  is non-null the grid is limited to those events (a targeted farm's own loot). */
	private List<ProfitLossCalculatorPanel.GridItem> gainGridItems(Set<IncomeEvent> only)
	{
		final boolean full = config.countUncollectedDrops();
		final Map<Integer, Integer> qty = new LinkedHashMap<>();
		for (IncomeEvent e : session.getIncome())
		{
			if (only != null && !only.contains(e))
			{
				continue;
			}
			(full ? e.getItems() : e.getCollected()).forEach((id, q) -> qty.merge(id, q, Integer::sum));
		}
		return gridItems(qty, this::lootValue);
	}

	/** Red grid: everything consumed - supplies, teleports, ammo, runes, skilling materials -
	 *  always GE priced. */
	private List<ProfitLossCalculatorPanel.GridItem> lossGridItems()
	{
		final Map<Integer, Integer> qty = new LinkedHashMap<>();
		for (CostEvent e : session.getEvents())
		{
			if (e.getType() == CostEvent.Type.CONSUMABLE || e.getType() == CostEvent.Type.TELEPORT)
			{
				qty.merge(ItemVariationMapping.map(e.getItemId()), e.getQuantity(), Integer::sum);
			}
			else if (e.getType() == CostEvent.Type.SKILLING)
			{
				// keep the exact item - a raw shark is not an anchovy
				qty.merge(e.getItemId(), e.getQuantity(), Integer::sum);
			}
		}
		session.getRunesUsed().forEach((id, q) -> qty.merge(id, q, Integer::sum));
		if (session.ammoTotal() > 0)
		{
			session.getAmmoStats().forEach((id, v) ->
			{
				if (v[2] > 0)
				{
					qty.merge(id, (int) v[2], Integer::sum);
				}
			});
		}
		session.getChargedWeaponsSpent().forEach((weapon, charges) ->
		{
			if (charges > 0)
			{
				weapon.materials(charges).forEach((id, q) -> qty.merge(id, q, Integer::sum));
			}
		});
		return gridItems(qty, (id, q) ->
			IncomeValuation.value(id, q, IncomeValuation.Mode.GE, priceLookup));
	}

	private interface ItemPricer
	{
		long value(int id, int qty);
	}

	private List<ProfitLossCalculatorPanel.GridItem> gridItems(Map<Integer, Integer> qty, ItemPricer pricer)
	{
		final List<ProfitLossCalculatorPanel.GridItem> out = new ArrayList<>();
		qty.forEach((id, q) ->
		{
			if (q > 0)
			{
				out.add(new ProfitLossCalculatorPanel.GridItem(
					id, q, pricer.value(id, q), itemName(id)));
			}
		});
		out.sort(Comparator.comparingLong(ProfitLossCalculatorPanel.GridItem::getValue).reversed());
		return out;
	}

	/** {@code [id, qty, gp]} per item, gp frozen at the current (session-end) valuation. */
	private List<long[]> itemTriples(Map<Integer, Integer> m)
	{
		final List<long[]> out = new ArrayList<>();
		m.forEach((id, q) ->
		{
			if (q > 0)
			{
				out.add(new long[]{id, q, lootValue(id, q)});
			}
		});
		out.sort((x, y) -> Long.compare(y[2], x[2]));
		return out;
	}

	/** {@code [id, qty, gp]} triples (as produced by {@link #itemTriples}) -&gt; grid items,
	 *  resolving each id's display name. Mirrors {@code HistoryContent.gridItems()}. */
	private List<ProfitLossCalculatorPanel.GridItem> gridItems(List<long[]> items)
	{
		final List<ProfitLossCalculatorPanel.GridItem> out = new ArrayList<>();
		for (long[] it : items)
		{
			if (it == null || it.length < 2 || it[1] <= 0)
			{
				continue;
			}
			out.add(new ProfitLossCalculatorPanel.GridItem((int) it[0], (int) it[1],
				it.length >= 3 ? it[2] : 0, itemName((int) it[0])));
		}
		return out;
	}

	/**
	 * One live block per target mob in a Targeted farm, in the order they were added - reuses
	 * {@link #perMobRollup} (the same rollup that feeds History) so a mob's live numbers and its
	 * eventual history row always agree. A freshly added target with no kills yet still gets a
	 * zeroed block, so adding a mob shows it immediately rather than waiting for a first kill.
	 */
	private List<ProfitLossCalculatorPanel.MobFarmBlock> targetFarmMobBlocks()
	{
		final Map<String, RunRecord.MobRun> perMob = perMobRollup();
		final List<ProfitLossCalculatorPanel.MobFarmBlock> out = new ArrayList<>();
		for (String target : session.getTargetMobs())
		{
			RunRecord.MobRun mr = null;
			for (Map.Entry<String, RunRecord.MobRun> e : perMob.entrySet())
			{
				if (Session.nameMatches(e.getKey(), target))
				{
					mr = e.getValue();
					break;
				}
			}
			final long gained = mr == null ? 0 : mr.getGained();
			final long cost = mr == null ? 0 : mr.getCost();
			final int kills = mr == null ? 0 : mr.getKills();
			out.add(new ProfitLossCalculatorPanel.MobFarmBlock(target, kills, gained - cost, gained, cost,
				kills > 0 ? (gained - cost) / kills : 0,
				mr == null ? Collections.emptyList() : gridItems(mr.getItems())));
		}
		return out;
	}

	/**
	 * Income not attributed to a kill, grouped one row per source (a stray mob, a chest, a
	 * ground pickup, …). In a targeted farm this is the "Other income" section; in a plain
	 * session it is the whole income list.
	 */
	private List<ProfitLossCalculatorPanel.EventLine> incomeLines(Session s, Set<IncomeEvent> inKill)
	{
		final long floor = Math.max(0, config.ignoreIncomeBelow());

		final Map<String, long[]> agg = new LinkedHashMap<>();   // source -> {collected, dropped, drops}
		final Map<String, String> kind = new LinkedHashMap<>();
		final Map<String, Map<Integer, Integer>> items = new LinkedHashMap<>();

		for (IncomeEvent e : s.getIncome())
		{
			if (inKill.contains(e))
			{
				continue;
			}
			final String src = incomeSourceLabel(e);
			final long[] a = agg.computeIfAbsent(src, k -> new long[3]);
			a[0] += lootValue(countedItems(e));
			a[1] += lootValue(e.getItems());
			a[2]++;
			kind.putIfAbsent(src, incomeKind(e.getType()));
			final Map<Integer, Integer> im = items.computeIfAbsent(src, k -> new LinkedHashMap<>());
			countedItems(e).forEach((id, q) -> im.merge(id, q, Integer::sum));
		}

		final List<ProfitLossCalculatorPanel.EventLine> lines = new ArrayList<>();
		agg.forEach((src, a) ->
		{
			if (a[1] < floor)
			{
				return;
			}
			final StringBuilder tip = new StringBuilder("<html>")
				.append(a[2]).append(a[2] == 1 ? " drop" : " drops");
			if (a[0] < a[1])
			{
				tip.append("  ·  ").append(gp(a[0])).append(" of ").append(gp(a[1])).append(" picked up");
			}
			final String named = namedItemsText(items.get(src));
			if (!named.isEmpty())
			{
				tip.append("<br>").append(named);
			}
			tip.append("</html>");
			lines.add(new ProfitLossCalculatorPanel.EventLine(kind.get(src), "", src, a[0], tip.toString()));
		});
		lines.sort(Comparator.comparingLong(ProfitLossCalculatorPanel.EventLine::getGp).reversed());
		return lines;
	}

	private static String incomeKind(IncomeEvent.Type t)
	{
		switch (t)
		{
			case NPC_LOOT:
				return "npc_loot";
			case PLAYER_LOOT:
				return "pvp_loot";
			case EVENT_LOOT:
				return "event_loot";
			case PICKPOCKET:
				return "pickpocket";
			case ALCH:
				return "alch";
			case SKILLING:
				return "skilling_gain";
			case PICKUP:
			default:
				return "pickup";
		}
	}

	private static String incomeSourceLabel(IncomeEvent e)
	{
		switch (e.getType())
		{
			case PICKUP:
				return "Picked up";
			case PLAYER_LOOT:
				return e.getSource() + " (kill)";
			default:
				return e.getSource();
		}
	}

	private List<ProfitLossCalculatorPanel.EventLine> eventLines(Session s)
	{
		final List<ProfitLossCalculatorPanel.EventLine> lines = new ArrayList<>();
		for (CostEvent ev : s.getEvents())
		{
			final String kind;
			final String label;
			switch (ev.getType())
			{
				case SPELL:
					kind = "spell";
					label = ev.getLabel();
					break;
				case TELEPORT:
					kind = "teleport";
					label = ev.getLabel();
					break;
				case SKILLING:
					kind = "skilling";
					label = ev.getQuantity() > 1 ? ev.getQuantity() + "× " + ev.getLabel() : ev.getLabel();
					break;
				default:
					kind = "supplies";
					label = consumableLabel(ev.getLabel());
					break;
			}
			lines.add(new ProfitLossCalculatorPanel.EventLine(
				kind, LINE_TIME.format(ev.getTime()), label, ev.getGp(), breakdownText(ev.getDetail())));
		}
		for (DeathEntry d : s.getDeaths())
		{
			if (!d.isCounted())
			{
				continue;
			}
			final String label = d.getState() == DeathEntry.State.LOST
				? "Death - lost (not reclaimed)"
				: "Death - reclaimed";
			lines.add(new ProfitLossCalculatorPanel.EventLine(
				"death",
				LINE_TIME.format(d.getDeathTime()),
				label,
				d.getResolvedCost(),
				namedItemsText(d.getLostItems())));
		}
		lines.sort(Comparator.comparing(ProfitLossCalculatorPanel.EventLine::getTime));

		if (s.ammoTotal() > 0)
		{
			lines.add(new ProfitLossCalculatorPanel.EventLine(
				"ammo", "", "Ammo used", s.ammoTotal(), ammoBreakdown(s.getAmmoStats())));
		}
		if (s.chargedWeaponTotal() > 0)
		{
			lines.add(new ProfitLossCalculatorPanel.EventLine(
				"ammo", "", "Weapon charges", s.chargedWeaponTotal(), chargedWeaponBreakdown(s)));
		}
		return lines;
	}

	/** "Venator bow — 4,213 charges — 80k" per line, most-charged first. */
	private String chargedWeaponBreakdown(Session s)
	{
		final List<Map.Entry<ChargedWeapon, Long>> rows = new ArrayList<>(s.getChargedWeaponsSpent().entrySet());
		rows.sort((a, b) -> Long.compare(b.getValue(), a.getValue()));
		final StringBuilder sb = new StringBuilder("<html>");
		int shown = 0;
		for (Map.Entry<ChargedWeapon, Long> e : rows)
		{
			if (e.getValue() <= 0)
			{
				continue;
			}
			if (shown++ > 0)
			{
				sb.append("<br>");
			}
			sb.append(e.getKey().getLabel()).append(" — ")
				.append(QuantityFormatter.formatNumber(e.getValue())).append(" charges — ")
				.append(gp(e.getKey().cost(e.getValue(), priceLookup::ge)));
		}
		sb.append("</html>");
		return shown == 0 ? null : sb.toString();
	}

	/** "Adamant dart — 540 fired, 120 recovered, 420 charged" per line, most-charged first. */
	private String ammoBreakdown(Map<Integer, long[]> stats)
	{
		final List<Map.Entry<Integer, long[]>> rows = new ArrayList<>(stats.entrySet());
		rows.sort((a, b) -> Long.compare(b.getValue()[2], a.getValue()[2]));

		final StringBuilder sb = new StringBuilder("<html>");
		int shown = 0;
		for (Map.Entry<Integer, long[]> e : rows)
		{
			final long[] v = e.getValue();
			if (v[0] <= 0)
			{
				continue;
			}
			if (shown == 8)
			{
				sb.append("…<br>");
				break;
			}
			if (shown > 0)
			{
				sb.append("<br>");
			}
			sb.append(itemName(e.getKey())).append(" — ").append(v[0]).append(" fired");
			if (v[1] > 0)
			{
				sb.append(", ").append(v[1]).append(" recovered");
			}
			sb.append(", ").append(v[2]).append(" charged");
			shown++;
		}
		sb.append("</html>");
		return shown == 0 ? null : sb.toString();
	}

	private static final Pattern DOSE_SUFFIX = Pattern.compile("\\(\\d\\)\\s*$");

	/** "Prayer potion(3)" -> "Prayer potion (sip)"; leaves un-dosed food untouched. */
	private static String consumableLabel(String name)
	{
		if (name == null)
		{
			return "";
		}
		final Matcher m = DOSE_SUFFIX.matcher(name);
		return m.find() ? name.substring(0, m.start()).trim() + " (sip)" : name;
	}

	private static String breakdownText(Map<String, Long> detail)
	{
		if (detail == null || detail.isEmpty())
		{
			return null;
		}
		final StringBuilder sb = new StringBuilder();
		detail.forEach((k, v) ->
		{
			if (sb.length() > 0)
			{
				sb.append(", ");
			}
			sb.append(k).append(" = ").append(v);
		});
		return sb.toString();
	}

	private Map<String, Object> namedItems(Map<Integer, Integer> items)
	{
		final Map<String, Object> out = new LinkedHashMap<>();
		items.forEach((id, qty) -> out.put(itemName(id) + " (" + id + ")", qty));
		return out;
	}

	private Map<String, Object> ammoItemsLog(Map<Integer, long[]> stats)
	{
		if (stats.isEmpty())
		{
			return null;
		}
		final Map<String, Object> out = new LinkedHashMap<>();
		stats.forEach((id, v) ->
		{
			final Map<String, Object> row = new LinkedHashMap<>();
			row.put("fired", v[0]);
			row.put("recovered", v[1]);
			row.put("charged", v[2]);
			out.put(itemName(id) + " (" + id + ")", row);
		});
		return out;
	}

	private Map<String, Object> chargedWeaponsLog()
	{
		if (session == null || session.getChargedWeaponsSpent().isEmpty())
		{
			return null;
		}
		final Map<String, Object> out = new LinkedHashMap<>();
		session.getChargedWeaponsSpent().forEach((w, charges) ->
		{
			if (charges > 0)
			{
				final Map<String, Object> row = new LinkedHashMap<>();
				row.put("charges", charges);
				row.put("gp", w.cost(charges, priceLookup::ge));
				out.put(w.getLabel(), row);
			}
		});
		return out.isEmpty() ? null : out;
	}

	/** Per-kill loot breakdown for the session_stop line. */
	private List<Map<String, Object>> killsLog()
	{
		if (session == null || session.getKills().isEmpty())
		{
			return null;
		}
		final List<Map<String, Object>> out = new ArrayList<>();
		for (BossKill k : session.getKills())
		{
			long dropped = 0;
			long collected = 0;
			final Map<Integer, Integer> items = new LinkedHashMap<>();
			for (IncomeEvent e : k.getDrops())
			{
				dropped += lootValue(e.getItems());
				collected += lootValue(e.getCollected());
				e.getItems().forEach((id, qty) -> items.merge(id, qty, Integer::sum));
			}
			final Map<String, Object> row = new LinkedHashMap<>();
			row.put("kill", k.getIndex());
			row.put("name", k.getName());
			row.put("at", k.getTime().toString());
			row.put("droppedGp", dropped);
			row.put("collectedGp", collected);
			row.put("items", namedItems(items));
			out.add(row);
		}
		return out;
	}

	private String namedItemsText(Map<Integer, Integer> items)
	{
		final StringBuilder sb = new StringBuilder();
		int shown = 0;
		for (Map.Entry<Integer, Integer> e : items.entrySet())
		{
			if (shown == 4)
			{
				sb.append(", +").append(items.size() - shown).append(" more");
				break;
			}
			if (shown > 0)
			{
				sb.append(", ");
			}
			sb.append(e.getValue()).append("× ").append(itemName(e.getKey()));
			shown++;
		}
		return sb.toString();
	}

	private String itemName(int itemId)
	{
		try
		{
			return itemManager.getItemComposition(itemId).getName();
		}
		catch (RuntimeException ex)
		{
			return "Item " + itemId;
		}
	}

	private static String gp(long value)
	{
		return QuantityFormatter.formatNumber(value) + " gp";
	}
}

